import { PhChecks } from "@phosphor-icons/vue";
import { Button } from "@pisagor/vue";
import { defineComponent, h } from "vue";
import { Alert } from "../../src/components/alert";
export default defineComponent({
  name: "Compound",
  setup() {
    return () =>
      h(Alert.Root, { variant: "info" }, () => [
        h(PhChecks),
        h(Alert.Title, null, () => "Deployment successful"),
        h(
          Alert.Description,
          null,
          () => "You can now start building your next great project.",
        ),
        h(Alert.Action, null, () => h(Button, { size: "xs" }, () => "Update")),
      ]);
  },
});

import { PhMagicWand } from "@phosphor-icons/vue";
import { defineComponent, h } from "vue";
import { Alert } from "../../src/components/alert";

export default defineComponent({
  name: "CustomColor",
  setup() {
    return () =>
      h(Alert, {
        classNames: undefined,
        description: "This alert uses a custom color.",
        icon: h(PhMagicWand),
        title: "Custom color alert",
        ...({
          class: "border-purple-500/32 bg-purple-500/5 [&_svg]:text-purple-500",
        } as Record<string, unknown>),
      });
  },
});

import {
  PhCheckCircle,
  PhChecks,
  PhClockCounterClockwise,
  PhWarning,
} from "@phosphor-icons/vue";
import { defineComponent, h } from "vue";
import { Alert } from "../../src/components/alert";

export default defineComponent({
  name: "Variants",
  setup() {
    return () =>
      h("div", { class: "flex flex-col gap-2" }, [
        h(Alert, {
          description: "You can now start building your next great project.",
          icon: h(PhChecks),
          title: "Deployment successful",
          variant: "default",
        }),
        h(Alert, {
          description: "Your session has expired. Please log in again.",
          icon: h(PhWarning),
          title: "Session expired",
          variant: "destructive",
        }),
        h(Alert, {
          description:
            "A new update is available. Review the update when you're ready.",
          icon: h(PhClockCounterClockwise),
          title: "New update available",
          variant: "info",
        }),
        h(Alert, {
          description:
            "Your payment has been processed successfully. You will receive a receipt in your email.",
          icon: h(PhCheckCircle),
          title: "Payment successful",
          variant: "success",
        }),
        h(Alert, {
          description:
            "Your storage is almost full. Consider upgrading your plan to avoid losing data.",
          icon: h(PhWarning),
          title: "Storage almost full",
          variant: "warning",
        }),
      ]);
  },
});

import { PhClockCounterClockwise } from "@phosphor-icons/vue";
import { Button } from "@pisagor/vue";
import { defineComponent, h } from "vue";
import { Alert } from "../../src/components/alert";
export default defineComponent({
  name: "WithAction",
  setup() {
    return () =>
      h(Alert, {
        action: [
          h(Button, { size: "xs", variant: "ghost" }, () => "Ignore"),
          h(Button, { size: "xs" }, () => "Update"),
        ],
        description: "Review the update when you're ready.",
        icon: h(PhClockCounterClockwise),
        title: "New update available",
      });
  },
});

import { PhSparkle } from "@phosphor-icons/vue";
import { defineComponent, h } from "vue";
import { Alert } from "../../src/components/alert";

export default defineComponent({
  name: "WithIcon",
  setup() {
    return () =>
      h(Alert, {
        description:
          "Icons can be added to alerts to provide visual context and improve user experience.",
        icon: h(PhSparkle),
        title: "New feature available",
      });
  },
});

