import { ark } from "@ark-ui/vue/factory";
import type { AlertProps as AlertSharedProps } from "@pisagor/props";
import {
  type AlertRecipe,
  type AlertRecipeSlot,
  type AlertVariantProps,
  alertRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import {
  computed,
  defineComponent,
  h,
  type PropType,
  toValue,
  type VNodeChild,
} from "vue";
import type { VariantClassNames } from "../../internal/types";
import { createContext } from "../../internal/utils/create-context";

// #region Types
type AlertClassNames = VariantClassNames<AlertRecipeSlot>;

export interface AlertProps extends AlertSharedProps {
  action?: VNodeChild;
  actionProps?: Record<string, unknown>;
  class?: unknown;
  classNames?: AlertClassNames;
  description?: VNodeChild;
  descriptionProps?: Record<string, unknown>;
  icon?: VNodeChild;
  title?: VNodeChild;
  titleProps?: Record<string, unknown>;
}

interface AlertContextValue {
  classNames?: AlertClassNames;
  slots: AlertRecipe;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

// #region Context
const [provideAlertContext, , useAlertContextRef] =
  createContext("Alert")<AlertContextValue>();
// #endregion

// #region Parts
export const AlertRoot = defineComponent({
  inheritAttrs: false,
  name: "AlertRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<AlertClassNames>,
    },
    recipe: {
      default: alertRecipe,
      type: Function as PropType<typeof alertRecipe>,
    },
    variant: {
      default: undefined,
      type: String as PropType<AlertVariantProps["variant"]>,
    },
  },
  setup(props, { attrs, slots }) {
    const contextValue = computed(() => ({
      classNames: props.classNames,
      slots: props.recipe({ variant: props.variant }),
    }));

    provideAlertContext(contextValue);

    return () =>
      h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: contextValue.value.slots.base({ class: props.class }),
          "data-part": "root",
          "data-scope": "alert",
        },
        slots,
      );
  },
});

export const AlertTitle = defineComponent({
  inheritAttrs: false,
  name: "AlertTitle",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs, slots }) {
    const contextRef = useAlertContextRef();

    return () => {
      const contextValue = toValue(contextRef);
      if (!contextValue) {
        return null;
      }

      const { classNames, slots: variantSlots } = contextValue;

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.title({
            class: cn(props.class, classNames?.title),
          }),
          "data-part": "title",
          "data-scope": "alert",
        },
        slots,
      );
    };
  },
});

export const AlertDescription = defineComponent({
  inheritAttrs: false,
  name: "AlertDescription",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs, slots }) {
    const contextRef = useAlertContextRef();

    return () => {
      const contextValue = toValue(contextRef);
      if (!contextValue) {
        return null;
      }

      const { classNames, slots: variantSlots } = contextValue;

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.description({
            class: cn(props.class, classNames?.description),
          }),
          "data-part": "description",
          "data-scope": "alert",
        },
        slots,
      );
    };
  },
});

export const AlertAction = defineComponent({
  inheritAttrs: false,
  name: "AlertAction",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs, slots }) {
    const contextRef = useAlertContextRef();

    return () => {
      const contextValue = toValue(contextRef);
      if (!contextValue) {
        return null;
      }

      const { classNames, slots: variantSlots } = contextValue;

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.action({
            class: cn(props.class, classNames?.action),
          }),
          "data-part": "action",
          "data-scope": "alert",
        },
        slots,
      );
    };
  },
});

export const AlertShorthand = defineComponent({
  inheritAttrs: false,
  name: "AlertShorthand",
  props: {
    action: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    actionProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<AlertClassNames>,
    },
    description: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    descriptionProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    icon: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    title: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    titleProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    variant: {
      default: undefined,
      type: String as PropType<AlertVariantProps["variant"]>,
    },
  },
  setup(props, { attrs }) {
    return () => {
      const nodes: VNodeChild[] = [];

      if (props.icon !== undefined) {
        nodes.push(props.icon);
      }

      if (props.title !== undefined) {
        nodes.push(h(AlertTitle, props.titleProps, () => props.title));
      }

      if (props.description !== undefined) {
        nodes.push(
          h(AlertDescription, props.descriptionProps, () => props.description),
        );
      }

      if (props.action !== undefined) {
        nodes.push(h(AlertAction, props.actionProps, () => props.action));
      }

      return h(
        AlertRoot,
        {
          ...attrs,
          class: props.class,
          classNames: props.classNames,
          variant: props.variant,
        },
        () => nodes,
      );
    };
  },
});
// #endregion

import {
  AlertAction,
  AlertDescription,
  AlertRoot,
  AlertShorthand,
  AlertTitle,
} from "./alert";

export type { AlertProps } from "./alert";

export const Alert = Object.assign(AlertShorthand, {
  Action: AlertAction,
  Description: AlertDescription,
  Root: AlertRoot,
  Title: AlertTitle,
});

