    onOpenChange: {
      default: undefined,
      type: Function as PropType<(open: boolean) => void>,
    },
    open: { default: undefined, type: Boolean },
    placement: {
      default: "start",
      type: String as PropType<AppShellPlacement>,
    },
    position: {
      default: "fixed",
      type: String as PropType<AppShellRegionPosition>,
    },
    resizableProps: {
      default: undefined,
