          role: "checkbox",
        },
        () => [
          h(CheckboxPrimitive.Control as ArkPart, {}, () => [
            h(
              CheckboxPrimitive.Indicator as ArkPart,
              {
                class: slots.indicator(),
              },
              () => h(PhCheck),
            ),
            h(
              CheckboxPrimitive.Indicator as ArkPart,
              {
                class: slots.indicator(),
                indeterminate: true,
              },
              () => h(PhMinus),
            ),
          ]),
          h(CheckboxPrimitive.HiddenInput as ArkPart, {
            tabIndex: props.tabIndex,
          }),
        ],
