import { ark } from "@ark-ui/vue/factory";
import {
  ProgressRoot,
  ProgressValueText,
  useProgressContext,
} from "@ark-ui/vue/progress";
import type { CircularProgressProps as CircularProgressSharedProps } from "@pisagor/props";
import {
  type CircularProgressRecipeSlot,
  circularProgressRecipe,
} from "@pisagor/recipes";
import { computed, defineComponent, h, type PropType, type VNode } from "vue";
import type { VariantClassNames } from "../../internal/types";

// #region Types
type CircularProgressClassNames = VariantClassNames<CircularProgressRecipeSlot>;

export interface CircularProgressProps extends CircularProgressSharedProps {
  class?: unknown;
  classNames?: CircularProgressClassNames;
  indeterminate?: boolean;
  isValueVisible?: boolean;
  size?: number;
  thickness?: number;
  trackProps?: Record<string, unknown>;
  value?: number;
  valueProps?: Record<string, unknown>;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

// #region Parts
const CircularProgressTrack = defineComponent({
  inheritAttrs: false,
  name: "CircularProgressTrack",
  props: {
    classNames: {
      default: undefined,
      type: Object as PropType<CircularProgressClassNames>,
    },
    recipe: {
      default: circularProgressRecipe,
      type: Function as PropType<typeof circularProgressRecipe>,
    },
    size: { default: 32, type: Number },
    thickness: { default: 4, type: Number },
    trackProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
  },
  setup(props) {
    const progress = useProgressContext();

    return () => {
      const slots = props.recipe();
      const { max, min, value } = progress.value;
      const radius = props.size / 2 - props.thickness / 2;
      const circumference = 2 * Math.PI * radius;
      const range = Math.max(max - min, 1);
      const normalizedValue =
        value == null ? min : Math.min(Math.max(value, min), max);
      const percent = (normalizedValue - min) / range;
      const dashOffset = circumference * (1 - percent);

      return h(
        ark.svg as ArkPart,
        {
          ...props.trackProps,
          "aria-hidden": "true",
          class: slots.track({ class: props.classNames?.track }),
          "data-part": "circle",
          "data-scope": "circular-progress",
          height: props.size,
          viewBox: `0 0 ${props.size} ${props.size}`,
          width: props.size,
        },
        () => [
          h("circle", {
            cx: props.size / 2,
            cy: props.size / 2,
            "data-part": "track-bg",
            "data-scope": "circular-progress",
            r: radius,
            strokeWidth: props.thickness,
          }),
          h("circle", {
            class: slots.range({ class: props.classNames?.range }),
            cx: props.size / 2,
            cy: props.size / 2,
            "data-part": "range",
            "data-scope": "circular-progress",
            r: radius,
            strokeDasharray: circumference,
            strokeDashoffset: value == null ? circumference * 0.7 : dashOffset,
            strokeLinecap: "round",
            strokeWidth: props.thickness,
          }),
        ],
      );
    };
  },
});

const CircularProgressValue = defineComponent({
  inheritAttrs: false,
  name: "CircularProgressValue",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs }) {
    return () =>
      h(ProgressValueText as ArkPart, {
        ...attrs,
        class: props.class,
      });
  },
});

export const CircularProgress = defineComponent({
  inheritAttrs: false,
  name: "CircularProgress",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<CircularProgressClassNames>,
    },
    indeterminate: { default: false, type: Boolean },
    isValueVisible: { default: undefined, type: Boolean },
    recipe: {
      default: circularProgressRecipe,
      type: Function as PropType<typeof circularProgressRecipe>,
    },
    size: { default: 32, type: Number },
    thickness: { default: 4, type: Number },
    trackProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    value: { default: undefined, type: Number },
    valueProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
  },
  setup(props, { attrs, slots }) {
    const slotsVariants = computed(() => props.recipe());

    return () => {
      const variantSlots = slotsVariants.value;
      const children: VNode[] = [];

      if (props.isValueVisible) {
        children.push(
          h(
            "span",
            {
              class: variantSlots.valueWrapper({
                class: props.classNames?.valueWrapper,
              }),
            },
            () =>
              h(CircularProgressValue as ArkPart, {
                ...props.valueProps,
                class: variantSlots.value({ class: props.classNames?.value }),
              }),
          ),
        );
      }

      const slotContent = slots.default?.();
      if (slotContent) {
        children.push(
          ...(Array.isArray(slotContent) ? slotContent : [slotContent]),
        );
      }

      children.push(
        h(CircularProgressTrack, {
          classNames: props.classNames,
          recipe: props.recipe,
          size: props.size,
          thickness: props.thickness,
          trackProps: props.trackProps,
        }),
      );

      return h(
        ProgressRoot as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
          modelValue: props.indeterminate ? null : props.value,
        },
        () => children,
      );
    };
  },
});
// #endregion

import {
  AngleSlider as AngleSliderPrimitive,
  useAngleSliderContext,
} from "@ark-ui/vue/angle-slider";
import type { CircularSliderProps as CircularSliderSharedProps } from "@pisagor/props";
import { circularSliderRecipe } from "@pisagor/recipes";
import {
  defineComponent,
  h,
  type PropType,
  reactive,
  toValue,
  unref,
  type VNodeChild,
  watchEffect,
} from "vue";
import { createContext } from "../../internal/utils/create-context";
import { FieldLabel } from "../field/field";

type ArkPart = Parameters<typeof h>[0];

// #region Types
interface CircularSliderContextValue {
  ringCircumference: number;
  ringRadius: number;
  size: number;
  slots: ReturnType<typeof circularSliderRecipe>;
  thickness: number;
  thumbSize: number;
}

export interface CircularSliderProps extends CircularSliderSharedProps {
  class?: unknown;
  defaultValue?: number;
  disabled?: boolean;
  /** Extra props forwarded to the hidden input element. */
  hiddenInputProps?: Record<string, unknown>;
  markers?: boolean | number[];
  markersAtSteps?: boolean;
  onValueChange?: (value: number) => void;
  size?: number;
  step?: number;
  thickness?: number;
  value?: number;
}
// #endregion

// #region Context
const [provideCircularSliderContext, , useCircularSliderContext] =
  createContext("CircularSlider")<CircularSliderContextValue>();
// #endregion

const CLOCK_MARKER_ANGLES = [0, 60, 120, 180, 240, 300];

// #region Parts
export const CircularSliderRoot = defineComponent({
  inheritAttrs: false,
  name: "CircularSliderRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    defaultValue: { default: undefined, type: Number },
    disabled: { default: undefined, type: Boolean },
    hiddenInputProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    markers: {
      default: undefined,
      type: [Boolean, Array] as PropType<boolean | number[] | undefined>,
    },
    markersAtSteps: { default: false, type: Boolean },
    onValueChange: {
      default: undefined,
      type: Function as PropType<CircularSliderProps["onValueChange"]>,
    },
    recipe: {
      default: circularSliderRecipe,
      type: Function as PropType<typeof circularSliderRecipe>,
    },
    size: { default: 100, type: Number },
    step: { default: 1, type: Number },
    thickness: { default: 6, type: Number },
    value: { default: undefined, type: Number },
  },
  setup(props, { attrs, slots }) {
    const variantSlots = props.recipe();
    const context = reactive<CircularSliderContextValue>({
      ringCircumference: 2 * Math.PI * (props.size / 2 - props.thickness / 2),
      ringRadius: props.size / 2 - props.thickness / 2,
      size: props.size,
      slots: variantSlots,
      thickness: props.thickness,
      thumbSize: Math.max(props.thickness + 8, 16),
    });

    watchEffect(() => {
      context.ringCircumference =
        2 * Math.PI * (props.size / 2 - props.thickness / 2);
      context.ringRadius = props.size / 2 - props.thickness / 2;
      context.size = props.size;
      context.thickness = props.thickness;
      context.thumbSize = Math.max(props.thickness + 8, 16);
    });

    provideCircularSliderContext(context);

    return () =>
      h(
        AngleSliderPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: context.slots.base({ class: props.class }),
          defaultValue: props.defaultValue,
          disabled: props.disabled,
          modelValue: props.value,
          onValueChange: props.onValueChange
            ? (details: { value: number }) =>
                props.onValueChange?.(details.value)
            : undefined,
          step: props.step,
          style: {
            "--thickness": `${props.thickness}px`,
            height: `${props.size}px`,
            width: `${props.size}px`,
          },
        },
        () => [
          h(CircularSliderControl, {
            markers: props.markers,
            markersAtSteps: props.markersAtSteps,
            step: props.step,
          }),
          slots.default?.(),
          h(AngleSliderPrimitive.HiddenInput as ArkPart, {
            ...props.hiddenInputProps,
          }),
        ],
      );
  },
});

export const CircularSliderControl = defineComponent({
  inheritAttrs: false,
  name: "CircularSliderControl",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    markers: {
      default: undefined,
      type: [Boolean, Array] as PropType<boolean | number[] | undefined>,
    },
    markersAtSteps: { default: false, type: Boolean },
    step: { default: 1, type: Number },
  },
  setup(props, { attrs }) {
    const contextRef = useCircularSliderContext();

    return () => {
      const context = toValue(contextRef);
      if (!context) return null;

      const markerValues =
        Array.isArray(props.markers) && props.markers.length > 0
          ? props.markers
          : props.markers === true
            ? props.markersAtSteps
              ? Array.from(
                  { length: Math.floor(360 / props.step) },
                  (_, i) => i * props.step,
                )
              : CLOCK_MARKER_ANGLES
            : null;

      return h(
        AngleSliderPrimitive.Control as ArkPart,
        {
          ...attrs,
          class: context.slots.control({ class: props.class }),
        },
        () => [
          h(CircularSliderProgressRing),
          markerValues
            ? h(CircularSliderMarkerGroup, {}, () =>
                markerValues.map((value) =>
                  h(CircularSliderMarker, { key: value, value }),
                ),
              )
            : null,
          h(CircularSliderThumb),
        ],
      );
    };
  },
});

const CircularSliderProgressRing = defineComponent({
  name: "CircularSliderProgressRing",
  setup() {
    const api = useAngleSliderContext();
    const contextRef = useCircularSliderContext();

    return () => {
      const context = toValue(contextRef);
      if (!context) return null;
      const { size, thickness, ringRadius, ringCircumference, slots } = context;

      const percent = unref(api).value / 360;
      const dashLength = percent * ringCircumference;
      const gapLength = ringCircumference - dashLength;
      const center = size / 2;

      return h(
        "svg",
        {
          "aria-hidden": "true",
          class: slots.ring(),
          height: size,
          viewBox: `0 0 ${size} ${size}`,
          width: size,
        },
        [
          h("circle", {
            class: slots.ringTrack(),
            cx: center,
            cy: center,
            fill: "transparent",
            r: ringRadius,
            strokeWidth: thickness,
          }),
          h("circle", {
            class: slots.ringRange(),
            cx: center,
            cy: center,
            fill: "transparent",
            r: ringRadius,
            strokeDasharray: `${dashLength} ${gapLength}`,
            strokeWidth: thickness,
          }),
        ],
      );
    };
  },
});

export const CircularSliderThumb = defineComponent({
  inheritAttrs: false,
  name: "CircularSliderThumb",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs }) {
    const contextRef = useCircularSliderContext();

    return () => {
      const context = toValue(contextRef);
      if (!context) return null;
      const { thumbSize, ringRadius, slots } = context;
      const halfThumb = thumbSize / 2;

      return h(
        AngleSliderPrimitive.Thumb as ArkPart,
        {
          ...attrs,
          class: slots.thumb({ class: props.class }),
          style: {
            "--size": `${thumbSize}px`,
          },
        },
        () =>
          h("span", {
            class: slots.thumbHandle(),
            style: {
              insetBlockStart: `calc(50% - ${ringRadius}px - ${halfThumb}px)`,
              insetInlineStart: `calc(50% - ${halfThumb}px)`,
            },
          }),
      );
    };
  },
});

export const CircularSliderValueText = defineComponent({
  inheritAttrs: false,
  name: "CircularSliderValueText",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    prefix: {
      default: "",
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    suffix: {
      default: "",
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
  },
  setup(props, { attrs }) {
    const api = useAngleSliderContext();
    const contextRef = useCircularSliderContext();

    return () => {
      const context = toValue(contextRef);
      if (!context) return null;

      return h(FieldLabel as ArkPart, { asChild: true }, () =>
        h(
          AngleSliderPrimitive.ValueText as ArkPart,
          {
            ...attrs,
            class: context.slots.value({ class: props.class }),
          },
          () => [props.prefix, " ", unref(api).value, " ", props.suffix],
        ),
      );
    };
  },
});

export const CircularSliderMarkerGroup = defineComponent({
  inheritAttrs: false,
  name: "CircularSliderMarkerGroup",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs, slots }) {
    const contextRef = useCircularSliderContext();

    return () => {
      const context = toValue(contextRef);
      if (!context) return null;

      return h(
        AngleSliderPrimitive.MarkerGroup as ArkPart,
        {
          ...attrs,
          class: context.slots.markerGroup({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const CircularSliderMarker = defineComponent({
  inheritAttrs: false,
  name: "CircularSliderMarker",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    value: { required: true, type: Number },
  },
  setup(props, { attrs }) {
    const contextRef = useCircularSliderContext();

    return () => {
      const context = toValue(contextRef);
      if (!context) return null;
      const { size, thickness, slots } = context;

      const ringRadius = size / 2 - thickness / 2;
      const markerHeight = Math.max(8, Math.min(thickness * 1.1, 16));
      const markerWidth = Math.max(4, Math.min(thickness * 0.4, 6));
      const markerOffset =
        size / 2 - ringRadius - markerHeight / 2 + (thickness + 4);

      return h(AngleSliderPrimitive.Marker as ArkPart, {
        ...attrs,
        class: slots.marker({ class: props.class }),
        style: {
          "--marker-height": `${markerHeight}px`,
          "--marker-offset": `${markerOffset}px`,
          "--marker-width": `${markerWidth}px`,
        },
        value: props.value,
      });
    };
  },
});
// #endregion

import {
  CircularSliderControl,
  CircularSliderMarker,
  CircularSliderMarkerGroup,
  CircularSliderRoot,
  CircularSliderThumb,
  CircularSliderValueText,
} from "./circular-slider";

export type { CircularSliderProps } from "./circular-slider";

export const CircularSlider = Object.assign(CircularSliderRoot, {
  Control: CircularSliderControl,
  Marker: CircularSliderMarker,
  MarkerGroup: CircularSliderMarkerGroup,
  Thumb: CircularSliderThumb,
  ValueText: CircularSliderValueText,
});

import { ClientOnly as ClientOnlyPrimitive } from "@ark-ui/vue/client-only";
import { defineComponent, h } from "vue";

type ArkPart = Parameters<typeof h>[0];

// #region Component
export const ClientOnly = defineComponent({
  inheritAttrs: false,
  name: "ClientOnly",
  setup(_, { attrs, slots }) {
    return () =>
      h(
        ClientOnlyPrimitive as ArkPart,
        { ...attrs },
        {
          default: slots.default,
          fallback: slots.fallback,
        },
      );
  },
});
// #endregion

