import { Clipboard as ClipboardPrimitive } from "@ark-ui/vue/clipboard";
import { PhCheck, PhClipboard } from "@phosphor-icons/vue";
import type { ClipboardProps as ClipboardSharedProps } from "@pisagor/props";
import {
  type ClipboardRecipeSlot,
  type ClipboardVariantProps,
  clipboardRecipe,
  formControlShellRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";
import type { VariantClassNames } from "../../internal/types";
import { Button, type ButtonProps } from "../button";
import { useFormControlSurface } from "../surface/use-form-control-surface";

type FormControlVariant = "primary" | "secondary";

// #region Types
type ClipboardClassNames = VariantClassNames<ClipboardRecipeSlot>;

type ClipboardValueSize = ClipboardVariantProps["valueSize"];

export interface ClipboardProps extends ClipboardSharedProps {
  class?: unknown;
  /** Slot class names */
  classNames?: ClipboardClassNames;
  /**
   * Visual shell variant for input/value display modes.
   * Defaults to `primary`.
   */
  controlVariant?: FormControlVariant;
  /** Icon shown after a successful copy */
  copiedIcon?: VNodeChild;
  /** Icon shown before copying */
  copyIcon?: VNodeChild;
  /**
   * The initial value to be copied to the clipboard when rendered.
   * Use when you don't need to control the value of the clipboard.
   */
  defaultValue?: string;
  /** The ids of the elements in the clipboard. Useful for composition. */
  ids?: Partial<{ input: string; label: string; root: string }>;
  /** Optional label rendered above the control. */
  label?: string;
  /** Extra props forwarded to the label element */
  labelProps?: Record<string, unknown>;
  /** The function to be called when the value is copied to the clipboard */
  onStatusChange?: (details: { copied: boolean }) => void;
  /** The function to be called when the value changes */
  onValueChange?: (details: { value: string }) => void;
  /**
   * The timeout for the copy operation
   *
   * @defaultValue 3000
   */
  timeout?: number;
  /** Specifies the localized strings that identifies the accessibility elements and their states */
  translations?: { triggerLabel?: (copied: boolean) => string };
  /**
   * The controlled value of the clipboard.
   */
  value?: string;
  /**
   * Display mode for the copy control.
   *
   * @defaultValue "input"
   */
  variant?: "button" | "input" | "value";
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

// #region Component
export const Clipboard = defineComponent({
  inheritAttrs: false,
  name: "PisagorClipboard",
  props: {
    buttonAriaLabel: { default: "Copy to clipboard", type: String },
    buttonSize: {
      default: "icon-md",
      type: String as PropType<ButtonProps["size"]>,
    },
    buttonVariant: {
      default: undefined,
      type: String as PropType<ButtonProps["variant"]>,
    },
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<ClipboardClassNames>,
    },
    controlVariant: {
      default: undefined,
      type: String as PropType<FormControlVariant>,
    },
    copiedIcon: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    copyIcon: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    defaultValue: { default: undefined, type: String },
    ids: {
      default: undefined,
      type: Object as PropType<ClipboardProps["ids"]>,
    },
    label: { default: undefined, type: String },
    labelProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    onStatusChange: {
      default: undefined,
      type: Function as PropType<ClipboardProps["onStatusChange"]>,
    },
    onValueChange: {
      default: undefined,
      type: Function as PropType<ClipboardProps["onValueChange"]>,
    },
    recipe: {
      default: clipboardRecipe,
      type: Function as PropType<typeof clipboardRecipe>,
    },
    timeout: { default: undefined, type: Number },
    translations: {
      default: undefined,
      type: Object as PropType<ClipboardProps["translations"]>,
    },
    value: { default: undefined, type: String },
    valueSize: { default: "md", type: String as PropType<ClipboardValueSize> },
    variant: {
      default: "input",
      type: String as PropType<ClipboardProps["variant"]>,
    },
  },
  setup(props, { attrs }) {
    const surfaceVariant = useFormControlSurface();

    return () => {
      const resolved = {
        surfaceVariant,
        variant: props.controlVariant ?? ("primary" as FormControlVariant),
      };
      const shellArgs = {
        surfaceVariant: resolved.surfaceVariant,
        variant: resolved.variant,
      };
      const controlProps = { "data-variant": resolved.variant };
      const shellClassName = formControlShellRecipe({
        size: "md",
        ...shellArgs,
      });
      const slots_ = props.recipe({ valueSize: props.valueSize });

      const copiedIcon = props.copiedIcon ?? h(PhCheck);
      const copyIcon = props.copyIcon ?? h(PhClipboard);

      const control = h(
        ClipboardPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: cn(props.class),
          defaultValue: props.defaultValue,
          ids: props.ids,
          modelValue: props.value,
          onStatusChange: props.onStatusChange,
          onValueChange: props.onValueChange,
          timeout: props.timeout,
          translations: props.translations,
        },
        () =>
          h(
            ClipboardPrimitive.Control as ArkPart,
            {
              class: slots_.control({ class: props.classNames?.control }),
            },
            () => [
              props.variant === "input"
                ? h(ClipboardPrimitive.Input as ArkPart, {
                    ...controlProps,
                    class: cn(
                      shellClassName,
                      slots_.input({ class: props.classNames?.input }),
                    ),
                    readOnly: true,
                  })
                : null,

              props.variant === "value"
                ? h(ClipboardPrimitive.ValueText as ArkPart, {
                    ...controlProps,
                    class: cn(
                      shellClassName,
                      slots_.value({ class: props.classNames?.value }),
                    ),
                  })
                : null,

              h(ClipboardPrimitive.Trigger as ArkPart, { asChild: true }, () =>
                h(
                  Button,
                  {
                    "aria-label": props.buttonAriaLabel,
                    size: props.buttonSize,
                    type: "button",
                    variant: props.buttonVariant,
                  },
                  () =>
                    h(
                      ClipboardPrimitive.Indicator as ArkPart,
                      {
                        class: slots_.indicator({
                          class: props.classNames?.indicator,
                        }),
                      },
                      { copied: () => copiedIcon, default: () => copyIcon },
                    ),
                ),
              ),
            ],
          ),
      );

      if (!props.label) {
        return control;
      }

      return h(
        "div",
        { class: slots_.field({ class: props.classNames?.field }) },
        [
          h(
            "span",
            {
              ...props.labelProps,
              class: slots_.label({ class: props.classNames?.label }),
            },
            props.label,
          ),
          control,
        ],
      );
    };
  },
});
// #endregion

import { Collapsible as CollapsiblePrimitive } from "@ark-ui/vue/collapsible";
import { PhCaretDown } from "@phosphor-icons/vue";
import type { CollapsibleProps as CollapsibleRootSharedProps } from "@pisagor/props";
import { collapsibleRecipe } from "@pisagor/recipes";
import { defineComponent, h, type PropType } from "vue";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface CollapsibleRootProps extends CollapsibleRootSharedProps {
  class?: unknown;
}
// #endregion

// #region Parts
export const CollapsibleRoot = defineComponent({
  inheritAttrs: false,
  name: "CollapsibleRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    collapsedHeight: {
      default: undefined,
      type: [Number, String] as PropType<number | string>,
    },
    lazyMount: { default: true, type: Boolean },
    recipe: {
      default: collapsibleRecipe,
      type: Function as PropType<typeof collapsibleRecipe>,
    },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    const partialCollapse = props.collapsedHeight !== undefined;

    return () => {
      const variantSlots = props.recipe();

      return h(
        CollapsiblePrimitive.Root as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
          collapsedHeight: props.collapsedHeight,
          "data-partial-collapse": props.collapsedHeight ? "" : undefined,
          lazyMount: partialCollapse ? false : props.lazyMount,
          unmountOnExit: partialCollapse ? false : props.unmountOnExit,
        },
        slots,
      );
    };
  },
});

export const CollapsibleTrigger = defineComponent({
  inheritAttrs: false,
  name: "CollapsibleTrigger",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: collapsibleRecipe,
      type: Function as PropType<typeof collapsibleRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        CollapsiblePrimitive.Trigger as ArkPart,
        {
          ...attrs,
          class: variantSlots.trigger({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const CollapsibleContent = defineComponent({
  inheritAttrs: false,
  name: "CollapsibleContent",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: collapsibleRecipe,
      type: Function as PropType<typeof collapsibleRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        CollapsiblePrimitive.Content as ArkPart,
        {
          ...attrs,
          class: variantSlots.content(),
        },
        () => h("div", { class: props.class }, slots.default?.()),
      );
    };
  },
});

export const CollapsibleIndicator = defineComponent({
  inheritAttrs: false,
  name: "CollapsibleIndicator",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: collapsibleRecipe,
      type: Function as PropType<typeof collapsibleRecipe>,
    },
  },
  setup(props, { attrs, slots: children }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        CollapsiblePrimitive.Indicator as ArkPart,
        {
          ...attrs,
          class: variantSlots.indicator({ class: props.class }),
        },
        () => [
          children.default?.(),
          h(PhCaretDown, { class: variantSlots.icon() }),
        ],
      );
    };
  },
});
// #endregion

import {
  CollapsibleContent,
  CollapsibleIndicator,
  CollapsibleRoot,
  CollapsibleTrigger,
} from "./collapsible";

export type { CollapsibleRootProps } from "./collapsible";

export const Collapsible = Object.assign(CollapsibleRoot, {
  Content: CollapsibleContent,
  Indicator: CollapsibleIndicator,
  Trigger: CollapsibleTrigger,
});

import {
  ColorPicker as ColorPickerPrimitive,
  type ColorPickerValueChangeDetails,
  parseColor as parseColorArk,
  useColorPickerContext as useColorPicker,
} from "@ark-ui/vue/color-picker";
import { ark } from "@ark-ui/vue/factory";
import { PhCheck, PhEyedropper, PhX } from "@phosphor-icons/vue";
import type { ColorPickerProps as ColorPickerSharedProps } from "@pisagor/props";
import { colorPickerRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";

type FormControlVariant = "primary" | "secondary";

type ClassValue = Parameters<typeof cn>[0];

import { defineComponent, h, type PropType, Teleport } from "vue";
import { Button } from "../button";
import { InputGroup } from "../input-group";

type ArkPart = Parameters<typeof h>[0];

export interface ColorPickerProps extends ColorPickerSharedProps {
  class?: ClassValue;
  variant?: FormControlVariant;
  positioning?: unknown;
  lazyMount?: boolean;
  unmountOnExit?: boolean;
  value?: string;
  defaultValue?: string;
  clearable?: boolean;
  onValueChange?: (value: string) => void;
}

export const parseColor = parseColorArk;

function colorPickerTeleport(
  content: ReturnType<typeof h> | Array<ReturnType<typeof h>>,
) {
  return h(Teleport, { to: "body" }, () => content);
}

export const ColorPickerRoot = defineComponent({
  inheritAttrs: false,
  name: "ColorPicker",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    clearable: { default: false, type: Boolean },
    defaultValue: {
      default: undefined,
      type: String as PropType<string | undefined>,
    },
    lazyMount: { default: true, type: Boolean },
    onValueChange: {
      default: undefined,
      type: Function as PropType<ColorPickerProps["onValueChange"]>,
    },
    positioning: {
      default: { placement: "top-start" },
      type: Object as PropType<unknown>,
    },
    recipe: {
      default: colorPickerRecipe,
      type: Function as PropType<typeof colorPickerRecipe>,
    },
    unmountOnExit: { default: true, type: Boolean },
    value: { default: undefined, type: String as PropType<string | undefined> },
    variant: {
      default: undefined,
      type: String as PropType<FormControlVariant | undefined>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const isControlled = props.value !== undefined;

      // Uncontrolled internal state is kept as a string; we parse on render.
      const internalValue =
        (isControlled ? undefined : props.defaultValue) ?? "";

      const handleValueChange = (details: ColorPickerValueChangeDetails) => {
        const next = (details as { valueAsString?: unknown }).valueAsString;
        if (!isControlled) {
          // internalValue is a constant here (simple wrapper); consumers can control via `value`.
        }
        props.onValueChange?.(typeof next === "string" ? next : "");
      };

      return h(
        ColorPickerPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: cn(
            props.recipe().base(),
            props.class,
            (attrs as { class?: ClassValue }).class,
          ),
          defaultValue: internalValue
            ? parseColorArk(internalValue)
            : undefined,
          lazyMount: props.lazyMount,
          onValueChange: props.onValueChange ? handleValueChange : undefined,
          positioning: props.positioning,
          unmountOnExit: props.unmountOnExit,
          value:
            isControlled && props.value
              ? parseColorArk(props.value)
              : undefined,
        },
        () => [
          slots.default?.(),
          h(ColorPickerPrimitive.HiddenInput as ArkPart),
        ],
      );
    };
  },
});

export const ColorPickerClearTrigger = defineComponent({
  inheritAttrs: false,
  name: "ColorPicker.ClearTrigger",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    clearable: { default: false, type: Boolean },
    onClick: {
      default: undefined,
      type: Function as PropType<((event: MouseEvent) => void) | undefined>,
    },
  },
  setup(props, { attrs }) {
    return () => {
      const api = useColorPicker();

      if (!props.clearable) {
        return null;
      }

      const apiTyped = api as {
        getControlProps?: () =>
          | { disabled?: boolean; readOnly?: boolean }
          | undefined;
        value?: {
          getChannelValue?: (channel: string) => number | string | undefined;
        };
        setValue?: (value: unknown) => void;
      };

      const controlProps = apiTyped.getControlProps?.() as
        | { disabled?: boolean; readOnly?: boolean }
        | undefined;
      if (controlProps?.disabled || controlProps?.readOnly) {
        return null;
      }

      const isCleared =
        Number(apiTyped.value?.getChannelValue?.("alpha")) === 0;
      if (isCleared) {
        return null;
      }

      return h(InputGroup.Addon as ArkPart, { align: "inline-end" }, () =>
        h(
          InputGroup.Button as ArkPart,
          {
            ...attrs,
            "aria-label": "Clear color",
            class: cn(props.class, (attrs as { class?: ClassValue }).class),
            "data-part": "clear-trigger",
            "data-scope": "color-picker",
            onClick: (event: MouseEvent) => {
              apiTyped.setValue?.(parseColorArk("rgba(0, 0, 0, 0)"));
              props.onClick?.(event);
            },
            size: "icon-xs",
            type: "button",
            variant: "ghost",
          },
          () => h(PhX),
        ),
      );
    };
  },
});

export const ColorPickerControl = defineComponent({
  inheritAttrs: false,
  name: "ColorPicker.Control",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    clearable: { default: false, type: Boolean },
    recipe: {
      default: colorPickerRecipe,
      type: Function as PropType<typeof colorPickerRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      return h(
        ColorPickerPrimitive.Control as ArkPart,
        {
          ...attrs,
          class: cn(
            props.recipe().control(),
            props.class,
            (attrs as { class?: ClassValue }).class,
          ),
        },
        () => [
          slots.default?.(),
          props.clearable
            ? h(ColorPickerClearTrigger, { clearable: true })
            : null,
        ],
      );
    };
  },
});

export const ColorPickerTrigger = defineComponent({
  inheritAttrs: false,
  name: "ColorPicker.Trigger",
  setup(_, { attrs, slots }) {
    return () =>
      h(ColorPickerPrimitive.Trigger as ArkPart, { ...attrs }, () =>
        slots.default?.(),
      );
  },
});

export const ColorPickerTransparencyGrid = defineComponent({
  inheritAttrs: false,
  name: "ColorPicker.TransparencyGrid",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    recipe: {
      default: colorPickerRecipe,
      type: Function as PropType<typeof colorPickerRecipe>,
    },
  },
  setup(props, { attrs }) {
    return () =>
      h(ColorPickerPrimitive.TransparencyGrid as ArkPart, {
        ...attrs,
        class: cn(
          props.recipe().transparencyGrid(),
          props.class,
          (attrs as { class?: ClassValue }).class,
        ),
      });
  },
});

export const ColorPickerContent = defineComponent({
  inheritAttrs: false,
  name: "ColorPicker.Content",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    recipe: {
      default: colorPickerRecipe,
      type: Function as PropType<typeof colorPickerRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () =>
      colorPickerTeleport(
        h(ColorPickerPrimitive.Positioner as ArkPart, {}, () =>
          h(
            ColorPickerPrimitive.Content as ArkPart,
            {
              ...attrs,
              class: cn(
                props.recipe().content(),
                props.class,
                (attrs as { class?: ClassValue }).class,
              ),
            },
            () => slots.default?.(),
          ),
        ),
      );
  },
});

export const ColorPickerView = defineComponent({
  inheritAttrs: false,
  name: "ColorPicker.View",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    recipe: {
      default: colorPickerRecipe,
      type: Function as PropType<typeof colorPickerRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () =>
      h(
