export function ColumnFilters() {
  return {
    components: {
      Button,
      ColumnFilterHeader,
      ColumnFilterSelect,
      DataGrid,
      DataGridPaginationBar,
      DataGridShell,
      DataGridView,
      InputGroup,
      PhFunnel,
      PhMagnifyingGlass,
    },
    setup() {
      const columnFilters = ref<ColumnFiltersState>([]);
      const globalFilter = ref("");
      const baseColumns = userColumns();

      const columnsWithFilters = baseColumns.map((column) => {
        if (!("accessorKey" in column)) {
          return column;
        }

        if (column.accessorKey === "role" || column.accessorKey === "status") {
          return {
            ...column,
            header: ({
              column: tableColumn,
            }: HeaderContext<FullUser, unknown>) => {
              const values = Array.from(
                tableColumn.getFacetedUniqueValues()?.keys() ?? [],
              ).sort() as string[];

              return h(
                ColumnFilterHeader,
                { label: column.header as string },
                () =>
                  h(ColumnFilterSelect, {
                    items: ["All", ...values],
                    onValueChange: (value: string | string[]) => {
                      const next = Array.isArray(value) ? value[0] : value;
                      tableColumn.setFilterValue(
                        next === "All" ? undefined : next,
                      );
                    },
                    value: [
                      (tableColumn.getFilterValue() as string | undefined) ??
                        "All",
                    ],
                  }),
              );
            },
          };
        }

        if (column.accessorKey === "name" || column.accessorKey === "email") {
          return {
            ...column,
            header: ({
              column: tableColumn,
            }: HeaderContext<FullUser, unknown>) =>
              h(ColumnFilterHeader, { label: column.header as string }, () =>
                h("input", {
                  "aria-label": `Filter ${String(column.accessorKey)}`,
                  class:
                    "h-7 w-full min-w-0 rounded-md border bg-transparent px-2 text-sm outline-none focus:ring-1 focus:ring-primary",
                  onInput: (event: Event) =>
                    tableColumn.setFilterValue(
                      (event.target as HTMLInputElement).value,
                    ),
                  placeholder: "Filter…",
                  value:
                    (tableColumn.getFilterValue() as string | undefined) ?? "",
                }),
              ),
          };
        }

        if (
          column.accessorKey === "department" ||
          column.accessorKey === "joinedAt"
        ) {
          return {
            ...column,
            header: () =>
              h(ColumnFilterHeader, { label: column.header as string }),
          };
        }

        return column;
      });

      const initialState = { pagination: { pageIndex: 0, pageSize: 8 } };

      const handleColumnFiltersChange = (
        updater:
          | ColumnFiltersState
          | ((old: ColumnFiltersState) => ColumnFiltersState),
      ) => {
        columnFilters.value = applyUpdater(columnFilters.value, updater);
      };

      const handleGlobalFilterChange = (
        updater: string | ((old: string) => string),
      ) => {
        globalFilter.value = applyUpdater(globalFilter.value, updater);
      };

      const handleGlobalInput = (value: string) => {
        globalFilter.value = value;
      };

      const clearFilters = () => {
        columnFilters.value = [];
        globalFilter.value = "";
      };

      const state = computed(() => ({
        columnFilters: columnFilters.value,
        globalFilter: globalFilter.value,
      }));

      return {
        allUsers,
        clearFilters,
        columnsWithFilters,
        globalFilter,
        handleColumnFiltersChange,
        handleGlobalFilterChange,
        handleGlobalInput,
        initialState,
        state,
      };
    },
    template: `
        <DataGridShell>
          <DataGrid
            :columns="columnsWithFilters"
            :data="allUsers"
            :initialState="initialState"
            :onColumnFiltersChange="handleColumnFiltersChange"
            :onGlobalFilterChange="handleGlobalFilterChange"
            :state="state"
          >
            <DataGrid.Toolbar>
              <div class="flex flex-wrap items-center gap-2">
                <InputGroup>
                  <InputGroup.Addon>
                    <PhMagnifyingGlass />
                  </InputGroup.Addon>
                  <InputGroup.Input
                    aria-label="Search all columns"
                    :onValueChange="handleGlobalInput"
                    placeholder="Global search…"
                    :value="globalFilter"
                  />
                </InputGroup>
                <Button @click="clearFilters" size="sm" variant="outline">
                  <PhFunnel />
                  Clear filters
                </Button>
              </div>
            </DataGrid.Toolbar>
            <DataGridView :colSpan="6" filterHead />
            <DataGridPaginationBar />
          </DataGrid>
        </DataGridShell>
      `,
  };
}

