                  </DataGrid.HeaderRow>
                </DataGrid.Header>
              </Table.Header>
              <Table.Body>
                <DataGridExpandableBody :colSpan="5" :renderDetail="renderDetail" />
              </Table.Body>
            </Table>
          </DataGrid>
