export const DataGridVirtualBody = defineComponent({
  inheritAttrs: false,
  name: "DataGridVirtualBody",
  props: {
    empty: {
      default: undefined,
      type: [String, Number, Boolean, Object, Array] as PropType<
        VNodeChild | undefined
      >,
    },
    estimateSize: { default: 40, type: Number },
    overscan: { default: 8, type: Number },
    viewportHeight: { default: "24rem", type: String },
  },
  setup(props, { slots }) {
    const anchorRef = ref<HTMLTableRowElement | null>(null);
    const scrollElement = shallowRef<HTMLElement | null>(null);

    const findWrapper = () =>
      anchorRef.value?.closest(
        '[data-scope="table"][data-part="wrapper"]',
      ) as HTMLElement | null;

    const applyViewportHeight = () => {
      const wrapper = findWrapper();
      scrollElement.value = wrapper;

      if (wrapper) {
        wrapper.style.height = props.viewportHeight;
      }
    };

    onMounted(applyViewportHeight);
    watch(() => props.viewportHeight, applyViewportHeight);
    onBeforeUnmount(() => {
      const wrapper = findWrapper();

      if (wrapper) {
        wrapper.style.height = "";
      }
    });

    const { slots: variantSlots, table } =
      useDataGridContextBase() as unknown as DataGridContextValue<RowData>;

    const virtualizer = useVirtualizer(
      computed(() => ({
        count: table.getRowModel().rows.length,
        estimateSize: () => props.estimateSize,
        getScrollElement: () => scrollElement.value,
        overscan: props.overscan,
      })),
    );

    return () => {
      const rows = table.getRowModel().rows;

      if (rows.length === 0) {
        return [
          h("tr", { class: variantSlots.anchor(), ref: anchorRef }),
          props.empty ?? null,
        ];
      }

      const virtualRows = virtualizer.value.getVirtualItems();
      const paddingTop = virtualRows[0]?.start ?? 0;
      const paddingBottom =
        virtualizer.value.getTotalSize() -
        (virtualRows[virtualRows.length - 1]?.end ?? 0);

      return [
        paddingTop > 0
          ? h(
              "tr",
              {
                "data-part": "virtual-spacer",
                "data-scope": "data-grid",
                ref: anchorRef,
              },
              [
                h("td", {
                  colSpan: table.getAllColumns().length,
                  style: { height: `${paddingTop}px` },
                }),
              ],
            )
          : h("tr", { class: variantSlots.anchor(), ref: anchorRef }),
        ...virtualRows.map((virtualRow) => {
          const row = rows[virtualRow.index];

          if (!row) {
            return null;
          }

          return h(DataGridRowProvider, { key: row.id, row }, () =>
            slots.default?.(),
          );
        }),
        paddingBottom > 0
          ? h(
              "tr",
              { "data-part": "virtual-spacer", "data-scope": "data-grid" },
              [
                h("td", {
                  colSpan: table.getAllColumns().length,
                  style: { height: `${paddingBottom}px` },
                }),
              ],
            )
          : null,
      ];
    };
  },
});

export const DataGridRow = defineComponent({
  inheritAttrs: false,
  name: "DataGridRow",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    style: {
      default: undefined,
      type: Object as PropType<CSSProperties | undefined>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const { row } =
        useDataGridRowContextBase() as unknown as DataGridRowContextValue<RowData>;
      const { slots: variantSlots } =
        useDataGridContextBase() as unknown as DataGridContextValue<RowData>;

      return h(
        Table.Row as ArkPart,
        {
          ...attrs,
          "aria-expanded": row.getCanExpand() ? row.getIsExpanded() : undefined,
          "aria-selected": row.getIsSelected(),
          class: variantSlots.row({ class: props.class }),
          "data-depth": row.depth,
          "data-expanded": row.getIsExpanded() ? "true" : undefined,
          "data-grouped": row.getIsGrouped() ? "true" : undefined,
          "data-part": "row",
          "data-scope": "data-grid",
          "data-state": row.getIsSelected() ? "selected" : undefined,
          style: props.style,
        },
        () => slots.default?.(),
      );
    };
  },
});

export const DataGridCell = defineComponent({
  inheritAttrs: false,
  name: "DataGridCell",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    columnId: {
      default: undefined,
      type: String as PropType<string | undefined>,
    },
    style: {
      default: undefined,
      type: Object as PropType<CSSProperties | undefined>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const { table } =
        useDataGridContextBase() as unknown as DataGridContextValue<RowData>;
      const { row } =
        useDataGridRowContextBase() as unknown as DataGridRowContextValue<RowData>;
      const sizingEnabled = Boolean(table.options.enableColumnResizing);

      if (props.columnId) {
        const cell = row
          .getVisibleCells()
          .find((item) => item.column.id === props.columnId);

        if (!cell) {
          return null;
        }

        return h(
          Table.Cell as ArkPart,
          {
            ...attrs,
            class: props.class,
            "data-part": "cell",
            "data-scope": "data-grid",
            style: {
              ...columnSizeStyle(cell.column, sizingEnabled),
              ...props.style,
            },
          },
          () => slots.default?.() ?? renderDataGridCell(cell),
        );
      }

      return row.getVisibleCells().map((cell) =>
        h(
          Table.Cell as ArkPart,
          {
            ...attrs,
            class: props.class,
            "data-part": "cell",
            "data-scope": "data-grid",
            key: cell.id,
            style: {
              ...columnSizeStyle(cell.column, sizingEnabled),
              ...props.style,
            },
          },
          () => renderDataGridCell(cell),
        ),
      );
    };
  },
});

export const DataGridEmpty = defineComponent({
  inheritAttrs: false,
  name: "DataGridEmpty",
  props: {
