      return h(
        Table.Row as ArkPart,
        {
          ...attrs,
          class: props.class,
          "data-part": "empty",
          "data-scope": "data-grid",
        },
        () =>
          h(
            Table.Cell as ArkPart,
            { class: variantSlots.empty(), colSpan: span },
            () =>
              slots.default?.() ??
