import type { DataTableProps as DataTableSharedProps } from "@pisagor/props";
import { type DataTableRecipe, dataTableRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import type {
  Cell,
  HeaderGroup,
  Row,
  RowData,
  TableOptions,
  Table as TableType,
} from "@tanstack/vue-table";
import { useTable } from "@tanstack/vue-table";
import {
  computed,
  defineComponent,
  h,
  type PropType,
  type VNodeChild,
} from "vue";
import { Table } from "../components/table";
import type { ClassValue } from "../internal/types";
import { createContext } from "../internal/utils/create-context";
import {
  type DataTableFeatures,
  dataTableFeatures,
} from "./data-table.features";

type ArkPart = Parameters<typeof h>[0];

// #region Types
interface DataTableContextValue<TData extends RowData> {
  slots: DataTableRecipe;
  table: TableType<DataTableFeatures, TData>;
}

interface DataTableHeaderGroupContextValue<TData extends RowData> {
  headerGroup: HeaderGroup<DataTableFeatures, TData>;
}

interface DataTableRowContextValue<TData extends RowData> {
  row: Row<DataTableFeatures, TData>;
}

/**
 * @typeParam TData - Row shape passed to `columns` and `data`.
 */
export type DataTableProps<TData extends RowData = RowData> = {
  class?: unknown;
  /**
   * TanStack Table features. Defaults to the DataTable feature preset.
   *
   * @defaultValue dataTableFeatures
   */
  features?: DataTableFeatures;
} & DataTableSharedProps &
  Omit<TableOptions<DataTableFeatures, TData>, "features">;
// #endregion

// #region Context + Hooks
const [provideDataTableContext, useDataTableContextBase] =
  createContext("DataTable")<DataTableContextValue<RowData>>();

const [provideDataTableHeaderGroupContext, useDataTableHeaderGroupContextBase] =
  createContext("DataTableHeaderGroup")<
    DataTableHeaderGroupContextValue<RowData>
  >();

const [provideDataTableRowContext, useDataTableRowContextBase] =
  createContext("DataTableRow")<DataTableRowContextValue<RowData>>();

/**
 * Returns the TanStack Table instance from the nearest DataTable context.
 *
 * @typeParam TData - Row shape for the table context.
 * @returns The table instance for the current row model.
 */
export function useDataTable<TData extends RowData>() {
  return useDataTableContextBase() as unknown as DataTableContextValue<TData>["table"];
}

/**
 * Returns the header group from the nearest DataTable.Header context.
 *
 * @typeParam TData - Row shape for the table context.
 * @returns The active header group.
 */
export function useDataTableHeaderGroup<TData extends RowData>() {
  return useDataTableHeaderGroupContextBase() as unknown as DataTableHeaderGroupContextValue<TData>;
}

/**
 * Returns the row from the nearest DataTable.Row context.
 *
 * @typeParam TData - Row shape for the table context.
 * @returns The active table row.
 */
export function useDataTableRow<TData extends RowData>() {
  return useDataTableRowContextBase() as unknown as Row<
    DataTableFeatures,
    TData
  >;
}

function flexRender(template: unknown, context: unknown): VNodeChild {
  if (template === null || template === undefined) return null;
  if (typeof template === "function")
    return (template as (ctx: unknown) => VNodeChild)(context);
  return template as VNodeChild;
}

/**
 * Renders a table cell using the column definition's cell renderer.
 *
 * @typeParam TData - Row shape for the cell context.
 * @returns The rendered cell content, or null for placeholder cells.
 */
export function renderDataTableCell<TData extends RowData>(
  cell: Cell<DataTableFeatures, TData, unknown>,
): VNodeChild {
  if (cell.getIsPlaceholder()) {
    return null;
  }

  return flexRender(cell.column.columnDef.cell, cell.getContext());
}

export type { Cell, HeaderGroup, Row, TableType };
// #endregion

// #region Parts
export const DataTableRoot = defineComponent({
  inheritAttrs: false,
  name: "DataTableRoot",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    recipe: {
      default: dataTableRecipe,
      type: Function as PropType<typeof dataTableRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const options = new Proxy(
      {},
      {
        get(_target, key: string) {
          switch (key) {
            case "data":
              return (attrs.data as RowData[] | undefined) ?? [];
            case "features":
              return (
                (attrs.features as DataTableFeatures | undefined) ??
                dataTableFeatures
              );
            default:
              return (attrs as Record<string, unknown>)[key];
          }
        },
        getOwnPropertyDescriptor() {
          return { configurable: true, enumerable: true };
        },
        has(_target, key: string) {
          return key in attrs || key === "data" || key === "features";
        },
        ownKeys() {
          return Array.from(
            new Set([...Reflect.ownKeys(attrs), "data", "features"]),
          );
        },
      },
    ) as TableOptions<DataTableFeatures, RowData>;

    const table = useTable(options);
    const variantSlots = props.recipe();
    const contextValue = computed<DataTableContextValue<RowData>>(() => ({
      slots: variantSlots,
      table,
    }));

    provideDataTableContext(contextValue);

    return () =>
      h(
        "div" as ArkPart,
        {
          class: cn(variantSlots.base(), props.class),
          "data-part": "root",
          "data-scope": "data-table",
        },
        () => slots.default?.(),
      );
  },
});

export const DataTableHeader = defineComponent({
  inheritAttrs: false,
  name: "DataTableHeader",
  setup(_, { slots }) {
    return () => {
      const { table } =
        useDataTableContextBase() as unknown as DataTableContextValue<RowData>;

      return table
        .getHeaderGroups()
        .map((headerGroup) =>
          h(
            DataTableHeaderGroupProvider,
            { headerGroup, key: headerGroup.id },
            () => slots.default?.(),
          ),
        );
    };
  },
});

const DataTableHeaderGroupProvider = defineComponent({
  inheritAttrs: false,
  name: "DataTableHeaderGroupProvider",
  props: {
    headerGroup: {
      required: true,
      type: Object as PropType<HeaderGroup<DataTableFeatures, RowData>>,
    },
  },
  setup(props, { slots }) {
    provideDataTableHeaderGroupContext(
      computed(() => ({ headerGroup: props.headerGroup })),
    );

    return () => slots.default?.();
  },
});

export const DataTableHeaderRow = defineComponent({
  inheritAttrs: false,
  name: "DataTableHeaderRow",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    return () =>
      h(
        Table.Row as ArkPart,
        {
          ...attrs,
          class: cn(props.class),
          "data-part": "header-row",
          "data-scope": "data-table",
        },
        () => slots.default?.(),
      );
  },
});

export const DataTableHead = defineComponent({
  inheritAttrs: false,
  name: "DataTableHead",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    columnId: {
      default: undefined,
      type: String as PropType<string | undefined>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const { headerGroup } = useDataTableHeaderGroup<RowData>();

      const renderHeader = (
        header: HeaderGroup<DataTableFeatures, RowData>["headers"][number],
      ) =>
        h(
          Table.Head as ArkPart,
          {
            ...attrs,
            class: cn(props.class),
            "data-part": "head",
            "data-scope": "data-table",
            key: header.id,
          },
          () =>
            slots.default
              ? slots.default()
              : flexRender(header.column.columnDef.header, header.getContext()),
        );

      if (props.columnId) {
        const header = headerGroup.headers.find(
          (item) => item.column.id === props.columnId,
        );
        return header ? renderHeader(header) : null;
      }

      return headerGroup.headers.map((header) => renderHeader(header));
    };
  },
});

export const DataTableBody = defineComponent({
  inheritAttrs: false,
  name: "DataTableBody",
  props: {
    empty: {
      default: undefined,
      type: [String, Number, Boolean, Object, Array] as PropType<
        VNodeChild | undefined
      >,
    },
  },
  setup(props, { slots }) {
    return () => {
      const { table } =
        useDataTableContextBase() as unknown as DataTableContextValue<RowData>;
      const rows = table.getRowModel().rows;

      if (rows.length === 0) {
        return props.empty ?? null;
      }

      return rows.map((row) =>
        h(DataTableRowProvider, { key: row.id, row }, () => slots.default?.()),
      );
    };
  },
});

const DataTableRowProvider = defineComponent({
  inheritAttrs: false,
  name: "DataTableRowProvider",
  props: {
    row: {
      required: true,
      type: Object as PropType<Row<DataTableFeatures, RowData>>,
    },
  },
  setup(props, { slots }) {
    provideDataTableRowContext(computed(() => ({ row: props.row })));

    return () => slots.default?.();
  },
});

export const DataTableRow = defineComponent({
  inheritAttrs: false,
  name: "DataTableRow",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const { row } =
        useDataTableRowContextBase() as unknown as DataTableRowContextValue<RowData>;

      return h(
        Table.Row as ArkPart,
        {
          ...attrs,
          "aria-selected": row.getIsSelected(),
          class: cn(props.class),
          "data-part": "row",
          "data-scope": "data-table",
          "data-state": row.getIsSelected() ? "selected" : undefined,
        },
        () => slots.default?.(),
      );
    };
  },
});

export const DataTableCell = defineComponent({
  inheritAttrs: false,
  name: "DataTableCell",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    columnId: {
      default: undefined,
      type: String as PropType<string | undefined>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const { row } =
        useDataTableRowContextBase() as unknown as DataTableRowContextValue<RowData>;

      if (props.columnId) {
        const cell = row
          .getVisibleCells()
          .find((item) => item.column.id === props.columnId);

        if (!cell) {
          return null;
        }

        return h(
          Table.Cell as ArkPart,
          {
            ...attrs,
            class: cn(props.class),
            "data-part": "cell",
            "data-scope": "data-table",
          },
          () => slots.default?.() ?? renderDataTableCell(cell),
        );
      }

      return row.getVisibleCells().map((cell) =>
        h(
          Table.Cell as ArkPart,
          {
            ...attrs,
            class: cn(props.class),
            "data-part": "cell",
            "data-scope": "data-table",
            key: cell.id,
          },
          () => renderDataTableCell(cell),
        ),
      );
    };
  },
});

export const DataTableEmpty = defineComponent({
  inheritAttrs: false,
  name: "DataTableEmpty",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    colSpan: {
      default: undefined,
      type: Number as PropType<number | undefined>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const { slots: variantSlots, table } =
        useDataTableContextBase() as unknown as DataTableContextValue<RowData>;
      const span = props.colSpan ?? table.getAllColumns().length;

      return h(
        Table.Row as ArkPart,
        {
          ...attrs,
          class: cn(props.class),
          "data-part": "empty",
          "data-scope": "data-table",
        },
        () =>
          h(
            Table.Cell as ArkPart,
            { class: variantSlots.empty(), colSpan: span },
            () =>
              slots.default?.() ??
              "No results. Try a different search or clear filters.",
          ),
      );
    };
  },
});

export const DataTableToolbar = defineComponent({
  inheritAttrs: false,
  name: "DataTableToolbar",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const { slots: variantSlots } =
        useDataTableContextBase() as unknown as DataTableContextValue<RowData>;

      return h(
        "div" as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.toolbar(), props.class),
          "data-part": "toolbar",
          "data-scope": "data-table",
        },
        () => slots.default?.(),
      );
    };
  },
});

export const DataTableFooter = defineComponent({
  inheritAttrs: false,
  name: "DataTableFooter",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const { slots: variantSlots } =
        useDataTableContextBase() as unknown as DataTableContextValue<RowData>;

      return h(
        "div" as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.footer(), props.class),
          "data-part": "footer",
          "data-scope": "data-table",
        },
        () => slots.default?.(),
      );
    };
  },
});
// #endregion

import type {
  RowData,
  CellContext as TableCellContext,
  ColumnDef as TableColumnDef,
  HeaderContext as TableHeaderContext,
} from "@tanstack/vue-table";
import {
  DataTableBody,
  DataTableCell,
  DataTableEmpty,
  DataTableFooter,
  DataTableHead,
  DataTableHeader,
  DataTableHeaderRow,
  DataTableRoot,
  DataTableRow,
  DataTableToolbar,
  renderDataTableCell,
  useDataTable,
  useDataTableHeaderGroup,
  useDataTableRow,
} from "./data-table";
import type { DataTableFeatures } from "./data-table.features";

export type {
  ColumnVisibilityState as VisibilityState,
  PaginationState,
  RowSelectionState,
  SortingState,
} from "@tanstack/vue-table";
export type { DataTableProps, HeaderGroup, Row, TableType } from "./data-table";
export type { DataTableFeatures } from "./data-table.features";
export { dataTableFeatures } from "./data-table.features";

export const DataTable = Object.assign(DataTableRoot, {
  Body: DataTableBody,
  Cell: DataTableCell,
  Empty: DataTableEmpty,
  Footer: DataTableFooter,
  Head: DataTableHead,
  Header: DataTableHeader,
  HeaderRow: DataTableHeaderRow,
  Row: DataTableRow,
  Toolbar: DataTableToolbar,
});

export {
  renderDataTableCell,
  useDataTable,
  useDataTableHeaderGroup,
  useDataTableRow,
};

export type ColumnDef<TData extends RowData, TValue = unknown> = TableColumnDef<
  DataTableFeatures,
  TData,
  TValue
>;

export type CellContext<
  TData extends RowData,
  TValue = unknown,
> = TableCellContext<DataTableFeatures, TData, TValue>;

export type HeaderContext<
  TData extends RowData,
  TValue = unknown,
> = TableHeaderContext<DataTableFeatures, TData, TValue>;

import {
  DatePicker as DatePickerPrimitive,
  type DatePickerValueChangeDetails,
  useDatePickerContext as useDatePicker,
} from "@ark-ui/vue/date-picker";
import { PhCalendar, PhClock, PhX } from "@phosphor-icons/vue";
import type { DatePickerProps as DatePickerRootSharedProps } from "@pisagor/props";
import { datePickerRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";

type FormControlVariant = "primary" | "secondary";

type ClassValue = Parameters<typeof cn>[0];

import { computed, defineComponent, h, type PropType, ref, unref } from "vue";
import { Button } from "../button";
import type { InputProps } from "../input";
import { InputGroup } from "../input-group";
import { InputGroupRoot } from "../input-group/input-group-core";
import {
  provideDatePickerContext,
  useDatePickerContextRef,
} from "./date-picker.context";

// #region Types
export interface DatePickerRootProps extends DatePickerRootSharedProps {
  variant?: FormControlVariant;
  positioning?: unknown;
  onValueChange?: (value: unknown) => void;
  value?: unknown;
  defaultValue?: unknown;
}

export interface DatePickerTriggerProps extends DatePickerRootSharedProps {
  clearable?: boolean;
}

export interface DatePickerInputProps extends Omit<InputProps, "size"> {
  clearable?: boolean;
  variant?: FormControlVariant;
}

export interface DatePickerTimerProps extends InputProps {
  clearable?: boolean;
}

export interface DatePickerContentProps {
  showCalendar?: boolean;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

// #region Parts
export const DatePickerRoot = defineComponent({
  inheritAttrs: false,
  name: "DatePicker",
  props: {
    defaultValue: {
      default: undefined,
      type: null as unknown as PropType<unknown>,
    },
    onValueChange: {
      default: undefined,
      type: Function as PropType<DatePickerRootProps["onValueChange"]>,
    },
    positioning: {
      default: { placement: "top" },
      type: Object as PropType<unknown>,
    },
    value: { default: undefined, type: null as unknown as PropType<unknown> },
    variant: {
      default: undefined,
      type: String as PropType<FormControlVariant | undefined>,
    },
  },
  setup(props, { attrs, slots }) {
    provideDatePickerContext(
      computed(() => ({
        variant: props.variant,
      })),
    );

    return () =>
      h(
        DatePickerPrimitive.Root as ArkPart,
        {
          ...attrs,
          defaultValue: props.defaultValue,
          modelValue: props.value,
          onValueChange: props.onValueChange
            ? (details: DatePickerValueChangeDetails) =>
                props.onValueChange?.((details as { value?: unknown }).value)
            : undefined,
          positioning: props.positioning,
        },
        () => {
          return [slots.default?.()];
        },
      );
  },
});

export const DatePickerTrigger = defineComponent({
  inheritAttrs: false,
  name: "DatePicker.Trigger",
  props: {
    clearable: { default: false, type: Boolean },
    recipe: {
      default: datePickerRecipe,
      type: Function as PropType<typeof datePickerRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      return h(
        DatePickerPrimitive.Control as ArkPart,
        {
          ...attrs,
          class: props.recipe().control(),
        },
        () => [
          h(
            DatePickerPrimitive.Trigger as ArkPart,
            {
              ...attrs,
              class: props.recipe().trigger(),
            },
            () => slots.default?.(),
          ),
          props.clearable ? h(DatePickerClearTrigger) : null,
        ],
      );
    };
  },
});

export const DatePickerInput = defineComponent({
  inheritAttrs: false,
  name: "DatePicker.Input",
  props: {
    clearable: { default: false, type: Boolean },
    size: { default: undefined, type: String as PropType<InputProps["size"]> },
    variant: {
      default: undefined,
      type: String as PropType<FormControlVariant | undefined>,
    },
  },
  setup(props, { attrs }) {
    const contextRef = useDatePickerContextRef();

    return () => {
      const ctx = unref(contextRef);

      return h(DatePickerPrimitive.Control as ArkPart, { ...attrs }, () =>
        h(
          InputGroupRoot as ArkPart,
          {
            size: props.size,
            variant: props.variant ?? ctx?.variant,
          },
          () => [
            h(DatePickerPrimitive.Input as ArkPart, { asChild: true }, () =>
              h(InputGroup.Input as ArkPart, {
                clearable: false,
                ...attrs,
                type: "text",
              }),
            ),
            h(InputGroup.Addon, { align: "inline-end" }, () => [
              props.clearable ? h(DatePickerClearTrigger) : null,
              h(DatePickerPrimitive.Trigger as ArkPart, { asChild: true }, () =>
                h(
                  Button as ArkPart,
                  {
                    "aria-label": "Open calendar",
                    size: "icon-md",
                    variant: "ghost",
                  },
                  () => h(PhCalendar),
                ),
              ),
            ]),
          ],
        ),
      );
    };
  },
});

export const DatePickerClearTrigger = defineComponent({
  inheritAttrs: false,
  name: "DatePicker.ClearTrigger",
  setup(_, { attrs }) {
    return () => {
      const api = useDatePicker();

      const apiTyped = api as {
        disabled?: boolean;
        readOnly?: boolean;
        value?: unknown;
      };

      const disabled = apiTyped.disabled;
      const readOnly = apiTyped.readOnly;
      const value = apiTyped.value as unknown[];

      if (disabled || readOnly || !Array.isArray(value) || value.length === 0) {
        return null;
      }

      return h(
        DatePickerPrimitive.ClearTrigger as ArkPart,
        { asChild: true } as unknown as Parameters<typeof h>[1],
        () =>
          h(
            InputGroup.Button as ArkPart,
            {
              ...attrs,
              "aria-label": "Clear date",
              "data-part": "button",
              "data-scope": "input-group",
              size: "icon-xs",
              type: "button",
              variant: "ghost",
            },
            () => h(PhX),
          ),
      );
    };
  },
});

export const DatePickerTimer = defineComponent({
  inheritAttrs: false,
  name: "DatePicker.Timer",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    clearable: { default: false, type: Boolean },
    defaultValue: {
      default: undefined,
      type: [String, Number, Array] as PropType<unknown>,
    },
    disabled: { default: undefined, type: Boolean },
    onValueChange: {
      default: undefined,
      type: Function as PropType<((value: string) => void) | undefined>,
    },
    readOnly: { default: undefined, type: Boolean },
    recipe: {
      default: datePickerRecipe,
      type: Function as PropType<typeof datePickerRecipe>,
    },
    value: {
      default: undefined,
      type: [String, Number, Array] as PropType<unknown>,
    },
    variant: {
      default: undefined,
      type: String as PropType<FormControlVariant | undefined>,
    },
  },
  setup(props, { attrs }) {
    const contextRef = useDatePickerContextRef();
    const internalValue = ref(
      props.defaultValue !== undefined ? String(props.defaultValue) : "",
    );
    const isControlled = computed(() => props.value !== undefined);
    const current = computed(() =>
      isControlled.value ? String(props.value ?? "") : internalValue.value,
    );
    const canClear = computed(
      () =>
        props.clearable &&
        !props.disabled &&
        !props.readOnly &&
        current.value.length > 0,
    );

    const handleValueChange = (next: string) => {
      if (!isControlled.value) {
        internalValue.value = next;
      }
      props.onValueChange?.(next);
    };

    const handleClear = () => handleValueChange("");

    return () => {
      const ctx = unref(contextRef);

      return h(
        InputGroupRoot as ArkPart,
        {
          ...attrs,
          variant: props.variant ?? ctx?.variant,
        },
        () => [
          h(InputGroup.Addon, () => h(PhClock)),
          h(
            InputGroup.Input as ArkPart,
            {
              ...attrs,
              class: cn(
                props.recipe().timer(),
                props.class,
                (attrs as { class?: ClassValue }).class,
              ),
              clearable: false,
              disabled: props.disabled,
              onValueChange: handleValueChange,
              readOnly: props.readOnly,
              step: "1",
              type: "time",
              value: current.value,
            } as unknown as Parameters<typeof h>[1],
          ),
          canClear.value
            ? h(InputGroup.Addon, { align: "inline-end" }, () =>
                h(InputClearButton, { onClear: handleClear }),
              )
            : null,
        ],
      );
    };
  },
});

export const DatePickerContent = defineComponent({
  inheritAttrs: false,
  name: "DatePicker.Content",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    recipe: {
      default: datePickerRecipe,
      type: Function as PropType<typeof datePickerRecipe>,
    },
    showCalendar: { default: true, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const content = [
        h(
          DatePickerPrimitive.Content as ArkPart,
          {
            ...attrs,
            class: cn(
              props.recipe().content(),
              props.class,
              (attrs as { class?: ClassValue }).class,
            ),
          },
          () =>
            props.showCalendar && !slots.default
              ? [
                  h(DatePickerPrimitive.ViewControl as ArkPart, () => [
                    h(DatePickerPrimitive.PrevTrigger as ArkPart),
                    h(DatePickerPrimitive.MonthSelect as ArkPart),
                    h(DatePickerPrimitive.YearSelect as ArkPart),
                    h(DatePickerPrimitive.NextTrigger as ArkPart),
                  ]),
                  h(DatePickerPrimitive.Table as ArkPart),
                ]
              : slots.default?.(),
        ),
      ];

      return h(
        "teleport",
        { to: "body" } as unknown as Parameters<typeof h>[1],
        () => h(DatePickerPrimitive.Positioner as ArkPart, {}, () => content),
      );
    };
  },
});

export const DatePickerValueText = defineComponent({
  inheritAttrs: false,
  name: "DatePicker.ValueText",
  props: {
    recipe: {
      default: datePickerRecipe,
      type: Function as PropType<typeof datePickerRecipe>,
    },
  },
  setup(props, { attrs }) {
    return () =>
      h(DatePickerPrimitive.ValueText as ArkPart, {
        ...attrs,
        class: cn(
          props.recipe().valueText(),
          (attrs as { class?: ClassValue }).class,
        ),
      });
  },
});

export const DatePickerPresetTrigger = defineComponent({
  inheritAttrs: false,
  name: "DatePicker.PresetTrigger",
  props: {},
  setup(_, { attrs, slots }) {
    return () =>
      h(DatePickerPrimitive.PresetTrigger as ArkPart, { ...attrs }, () =>
        slots.default?.(),
      );
  },
});

// Small helper for the timer clear button.
const InputClearButton = defineComponent({
  inheritAttrs: false,
  name: "DatePicker.TimerClearButton",
  props: {
    onClear: { required: true, type: Function as PropType<() => void> },
  },
  setup(props) {
    return () =>
      h(
        InputGroup.Button as ArkPart,
        {
          "aria-label": "Clear time",
          onClick: props.onClear,
          size: "icon-xs",
          type: "button",
          variant: "ghost",
        },
        () => h(PhX),
      );
  },
});

export const DatePicker = Object.assign(DatePickerRoot, {
  ClearTrigger: DatePickerClearTrigger,
  Content: DatePickerContent,
  Input: DatePickerInput,
  PresetTrigger: DatePickerPresetTrigger,
  Timer: DatePickerTimer,
  Trigger: DatePickerTrigger,
  ValueText: DatePickerValueText,
});

import { createContext } from "../../internal/utils/create-context";

type FormControlVariant = "primary" | "secondary";

export interface DatePickerContextValue {
  variant?: FormControlVariant;
}

export const [provideDatePickerContext, , useDatePickerContextRef] =
  createContext("DatePicker")<DatePickerContextValue>({
    defaultValue: {},
    strict: false,
  });

export { parseDate } from "../calendar";
export type {
  DatePickerContentProps,
  DatePickerInputProps,
  DatePickerRootProps as DatePickerProps,
  DatePickerTimerProps,
  DatePickerTriggerProps,
} from "./date-picker";
export {
  DatePicker,
  DatePickerClearTrigger,
  DatePickerContent,
  DatePickerInput,
  DatePickerPresetTrigger,
  DatePickerTimer,
  DatePickerTrigger,
  DatePickerValueText,
} from "./date-picker";

