import { Drawer as DrawerPrimitive } from "@ark-ui/vue/drawer";
import type { DrawerProps as DrawerSharedProps } from "@pisagor/props";
import { type DrawerRecipe, drawerRecipe } from "@pisagor/recipes";
import { defineComponent, h, type PropType, reactive, Teleport } from "vue";
import { createContext } from "../../internal/utils/create-context";

// #region Types
interface DrawerContextValue {
  slots: DrawerRecipe;
}

export interface DrawerHeaderProps {
  class?: unknown;
  description?: string;
  title?: string;
}

export interface DrawerBodyProps {
  class?: unknown;
  scrollFade?: boolean;
}

export interface DrawerProps extends DrawerSharedProps {
  lazyMount?: boolean;
  unmountOnExit?: boolean;
}
// #endregion

// #region Context
const [provideDrawerContext, useDrawerLocal] = createContext(
  "DrawerLocal",
)<DrawerContextValue>({ strict: false });

function useDrawerSlots() {
  return useDrawerLocal()?.slots ?? drawerRecipe();
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

const SWIPE_DIRECTION_TO_PLACEMENT = {
  down: "down",
  end: "right",
  start: "left",
  up: "up",
} as const;

function drawerTeleport(
  content: ReturnType<typeof h> | ReturnType<typeof h>[],
) {
  return h(Teleport, { to: "body" }, () => content);
}

// #region Parts
export const DrawerRoot = defineComponent({
  inheritAttrs: false,
  name: "DrawerRoot",
  props: {
    recipe: {
      default: drawerRecipe,
      type: Function as PropType<typeof drawerRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const context = reactive<DrawerContextValue>({
      slots: props.recipe(),
    });
    provideDrawerContext(context);

    return () => h(DrawerPrimitive.Root as ArkPart, { ...attrs }, slots);
  },
});

export const DrawerTrigger = defineComponent({
  inheritAttrs: false,
  name: "DrawerTrigger",
  setup(_, { attrs, slots }) {
    return () => h(DrawerPrimitive.Trigger as ArkPart, { ...attrs }, slots);
  },
});

export const DrawerBackdrop = defineComponent({
  inheritAttrs: false,
  name: "DrawerBackdrop",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const drawerSlots = useDrawerSlots();

      return h(
        DrawerPrimitive.Backdrop as ArkPart,
        {
          ...attrs,
          class: drawerSlots.backdrop({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const DrawerPositioner = defineComponent({
  inheritAttrs: false,
  name: "DrawerPositioner",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    variant: {
      default: "default",
      type: String as PropType<"default" | "inset">,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const drawerSlots = useDrawerSlots();

      return h(
        DrawerPrimitive.Positioner as ArkPart,
        {
          ...attrs,
          class: drawerSlots.positioner({
            class: props.class,
            variant: props.variant,
          }),
        },
        slots,
      );
    };
  },
});

export const DrawerContent = defineComponent({
  inheritAttrs: false,
  name: "DrawerContent",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    variant: {
      default: "default",
      type: String as PropType<"default" | "inset">,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const drawerSlots = useDrawerSlots();

      return drawerTeleport([
        h(DrawerBackdrop),
        h(DrawerPrimitive.Context as ArkPart, null, {
          default: (drawerApi: {
            swipeDirection: keyof typeof SWIPE_DIRECTION_TO_PLACEMENT;
          }) =>
            h(DrawerPositioner, { variant: props.variant }, () =>
              h(
                DrawerPrimitive.Content as ArkPart,
                {
                  ...attrs,
                  class: drawerSlots.content({
                    class: props.class,
                    placement:
                      SWIPE_DIRECTION_TO_PLACEMENT[drawerApi.swipeDirection],
                    variant: props.variant,
                  }),
                },
                () => [h(DrawerGrabber), slots.default?.()],
              ),
            ),
        }),
      ]);
    };
  },
});

export const DrawerContentInner = defineComponent({
  inheritAttrs: false,
  name: "DrawerContentInner",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const drawerSlots = useDrawerSlots();

      return h(
        "div",
        {
          ...attrs,
          class: drawerSlots.contentInner({ class: props.class }),
          "data-part": "content-inner",
          "data-scope": "drawer",
        },
        slots,
      );
    };
  },
});

export const DrawerGrabber = defineComponent({
  inheritAttrs: false,
  name: "DrawerGrabber",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs, slots: children }) {
    return () => {
      const drawerSlots = useDrawerSlots();

      return h("div", { class: drawerSlots.grabberWrapper() }, () =>
        h(
          DrawerPrimitive.Grabber as ArkPart,
          {
            ...attrs,
            class: drawerSlots.grabber({ class: props.class }),
          },
          () => [
            h(DrawerPrimitive.GrabberIndicator as ArkPart, {
              class: drawerSlots.grabberIcon(),
            }),
            children.default?.(),
          ],
        ),
      );
    };
  },
});

export const DrawerHeader = defineComponent({
  inheritAttrs: false,
  name: "DrawerHeader",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    description: String,
    title: String,
  },
  setup(props, { attrs, slots }) {
    return () => {
      const drawerSlots = useDrawerSlots();

      return h(
        "div",
        {
          ...attrs,
          class: drawerSlots.header({ class: props.class }),
          "data-part": "header",
          "data-scope": "drawer",
        },
        () => [
          props.title ? h(DrawerTitle, null, () => props.title) : null,
          props.description
            ? h(DrawerDescription, null, () => props.description)
            : null,
          slots.default?.(),
        ],
      );
    };
  },
});

export const DrawerTitle = defineComponent({
  inheritAttrs: false,
  name: "DrawerTitle",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const drawerSlots = useDrawerSlots();

      return h(
        DrawerPrimitive.Title as ArkPart,
        {
          ...attrs,
          class: drawerSlots.title({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const DrawerDescription = defineComponent({
  inheritAttrs: false,
  name: "DrawerDescription",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const drawerSlots = useDrawerSlots();

      return h(
        "div",
        {
          ...attrs,
          class: drawerSlots.description({ class: props.class }),
          "data-part": "description",
          "data-scope": "drawer",
        },
        slots,
      );
    };
  },
});

export const DrawerBody = defineComponent({
  inheritAttrs: false,
  name: "DrawerBody",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    scrollFade: { default: false, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const drawerSlots = useDrawerSlots();

      return h(
        "div",
