import { type EmptyStateRecipeSlot, emptyStateRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";
import type { VariantClassNames } from "../../internal/types";

type ArkPart = Parameters<typeof h>[0];

// #region Types
type EmptyStateClassNames = VariantClassNames<EmptyStateRecipeSlot>;

export interface EmptyStateProps extends EmptyStateSharedProps {
  actions?: VNodeChild;
  class?: unknown;
  classNames?: EmptyStateClassNames;
  description?: VNodeChild;
  media?: VNodeChild;
  title?: VNodeChild;
}
// #endregion

// #region Parts
export const EmptyStateRoot = defineComponent({
  inheritAttrs: false,
  name: "EmptyStateRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<EmptyStateClassNames>,
    },
    recipe: {
      default: emptyStateRecipe,
      type: Function as PropType<typeof emptyStateRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const slots_ = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: slots_.base({ class: props.class }),
          "data-part": "root",
          "data-scope": "empty-state",
        },
        slots,
      );
    };
  },
});

function createEmptyStatePart(
  slot: Exclude<EmptyStateRecipeSlot, "base">,
  part: string,
) {
  return defineComponent({
    inheritAttrs: false,
    name: `EmptyState${slot.charAt(0).toUpperCase()}${slot.slice(1)}`,
    props: {
      class: {
        default: undefined,
        type: [String, Object, Array] as PropType<unknown>,
      },
      classNames: {
        default: undefined,
        type: Object as PropType<EmptyStateClassNames>,
      },
      recipe: {
        default: emptyStateRecipe,
        type: Function as PropType<NonNullable<EmptyStateProps["recipe"]>>,
      },
    },
    setup(props, { attrs, slots }) {
      const element =
        slot === "title" ? ark.h3 : slot === "description" ? ark.p : ark.div;

      return () => {
        const slots_ = props.recipe();

        return h(
          element as ArkPart,
          {
            ...attrs,
            class: slots_[slot]({
              class: cn(props.class, props.classNames?.[slot]),
            }),
            "data-part": part,
            "data-scope": "empty-state",
          },
          slots,
        );
      };
    },
  });
}

export const EmptyStateMedia = createEmptyStatePart("media", "media");
export const EmptyStateTitle = createEmptyStatePart("title", "title");
export const EmptyStateDescription = createEmptyStatePart(
  "description",
  "description",
);
export const EmptyStateActions = createEmptyStatePart("actions", "actions");

export const EmptyStateShorthand = defineComponent({
  inheritAttrs: false,
  name: "EmptyStateShorthand",
  props: {
    actions: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<EmptyStateClassNames>,
    },
    description: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    media: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    recipe: {
      default: emptyStateRecipe,
      type: Function as PropType<typeof emptyStateRecipe>,
    },
    title: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
  },
  setup(props, { attrs }) {
    return () =>
      h(
        EmptyStateRoot,
        {
          ...attrs,
          class: props.class,
          classNames: props.classNames,
          recipe: props.recipe,
        },
        () => [
          props.media !== undefined &&
            h(EmptyStateMedia, null, () => props.media),
          props.title !== undefined &&
            h(EmptyStateTitle, null, () => props.title),
          props.description !== undefined &&
            h(EmptyStateDescription, null, () => props.description),
          props.actions !== undefined &&
            h(EmptyStateActions, null, () => props.actions),
        ],
      );
  },
});
// #endregion

import {
  EmptyStateActions,
  EmptyStateDescription,
  EmptyStateMedia,
  EmptyStateRoot,
  EmptyStateShorthand,
  EmptyStateTitle,
} from "./empty-state";

export type { EmptyStateProps } from "./empty-state";

export const EmptyState = Object.assign(EmptyStateShorthand, {
  Actions: EmptyStateActions,
  Description: EmptyStateDescription,
  Media: EmptyStateMedia,
  Root: EmptyStateRoot,
  Title: EmptyStateTitle,
});

import { Field as FieldPrimitive } from "@ark-ui/vue/field";
import { Fieldset as FieldsetPrimitive } from "@ark-ui/vue/fieldset";
import type { FieldProps as FieldSharedProps } from "@pisagor/props";
import { fieldRecipe, formControlSeparatorRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType } from "vue";
import { Separator } from "../separator/separator";
import { useFormControlSurface } from "../surface/use-form-control-surface";

type FormControlVariant = "primary" | "secondary";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface FieldProps extends FieldSharedProps {
  class?: unknown;
  orientation?: "horizontal" | "responsive" | "vertical";
  reverse?: boolean;
}

export interface FieldLabelProps {
  asChild?: boolean;
  class?: unknown;
}
// #endregion

// #region Parts
export const FieldRoot = defineComponent({
  inheritAttrs: false,
  name: "FieldRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    orientation: {
      default: "vertical",
      type: String as PropType<FieldProps["orientation"]>,
    },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
    reverse: { default: false, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe({
        orientation: props.orientation,
        reverse: props.reverse,
      });

      return h(
        FieldPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.base(), props.class),
          "data-orientation": props.orientation,
        },
        slots,
      );
    };
  },
});

export const FieldSet = defineComponent({
  inheritAttrs: false,
  name: "FieldSet",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
