      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
    variant: {
      default: "legend",
      type: String as PropType<"label" | "legend">,
