import { ark } from "@ark-ui/vue/factory";
import { PhFile } from "@phosphor-icons/vue";
import type { FileProps as FileSharedProps } from "@pisagor/props";
import { type FileVariantProps, fileRecipe } from "@pisagor/recipes";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";
import { Format } from "../format";

export type FileMediaVariant = NonNullable<FileVariantProps["variant"]>;

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface FileProps extends FileSharedProps {
  class?: unknown;
  /** Leading media; defaults to a file icon. */
  media?: VNodeChild;
  /** Optional subtitle (type, modified date, etc.). */
  meta?: VNodeChild;
  /** Display name for the file. */
  name: VNodeChild;
  /** Size in bytes; rendered with `Format.Byte` when set. */
  size?: number;
}
// #endregion

// #region Parts
export const FileRoot = defineComponent({
  inheritAttrs: false,
  name: "FileRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: fileRecipe,
      type: Function as PropType<typeof fileRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
          "data-part": "root",
          "data-scope": "file",
        },
        slots,
      );
    };
  },
});

export const FileMedia = defineComponent({
  inheritAttrs: false,
  name: "FileMedia",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: fileRecipe,
      type: Function as PropType<typeof fileRecipe>,
    },
    variant: {
      default: "icon",
      type: String as PropType<FileVariantProps["variant"]>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.media({
            class: props.class,
            variant: props.variant,
          }),
          "data-part": "media",
          "data-scope": "file",
          "data-variant": props.variant,
        },
        () => slots.default?.() ?? h(PhFile),
      );
    };
  },
});

export const FileContent = defineComponent({
  inheritAttrs: false,
  name: "FileContent",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: fileRecipe,
      type: Function as PropType<typeof fileRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.content({ class: props.class }),
          "data-part": "content",
          "data-scope": "file",
        },
        slots,
      );
    };
  },
});

export const FileName = defineComponent({
  inheritAttrs: false,
  name: "FileName",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: fileRecipe,
      type: Function as PropType<typeof fileRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.name({ class: props.class }),
          "data-part": "name",
          "data-scope": "file",
        },
        slots,
      );
    };
  },
});

export const FileMeta = defineComponent({
  inheritAttrs: false,
  name: "FileMeta",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: fileRecipe,
      type: Function as PropType<typeof fileRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.meta({ class: props.class }),
          "data-part": "meta",
          "data-scope": "file",
        },
        slots,
      );
    };
  },
});

export const FileSize = defineComponent({
  inheritAttrs: false,
  name: "FileSize",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: fileRecipe,
      type: Function as PropType<typeof fileRecipe>,
    },
    value: { required: true, type: Number },
  },
  setup(props, { attrs }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.size({ class: props.class }),
          "data-part": "size",
          "data-scope": "file",
        },
        () => h(Format.Byte, { value: props.value }),
      );
    };
  },
});

export const FileActions = defineComponent({
  inheritAttrs: false,
  name: "FileActions",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: fileRecipe,
      type: Function as PropType<typeof fileRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.actions({ class: props.class }),
          "data-part": "actions",
          "data-scope": "file",
        },
        slots,
      );
    };
  },
});

export const FileShorthand = defineComponent({
  inheritAttrs: false,
  name: "FileShorthand",
  props: {
    actions: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    media: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    meta: {
      default: undefined,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    name: {
      required: true,
      type: [String, Object, Array] as PropType<VNodeChild>,
    },
    size: { default: undefined, type: Number },
  },
  setup(props, { attrs }) {
    return () =>
      h(FileRoot, { ...attrs, class: props.class }, () => [
        h(FileMedia, null, () => props.media),

        h(FileContent, null, () => [
          h(FileName, null, () => props.name),

          props.meta !== undefined ? h(FileMeta, null, () => props.meta) : null,

          props.size !== undefined ? h(FileSize, { value: props.size }) : null,
        ]),

        props.actions !== undefined
          ? h(FileActions, null, () => props.actions)
          : null,
      ]);
  },
});
// #endregion

import {
  FileActions,
  FileContent,
  FileMedia,
  FileMeta,
  FileName,
  FileRoot,
  FileShorthand,
  FileSize,
} from "./file";

export type { FileMediaVariant, FileProps } from "./file";

export const File = Object.assign(FileShorthand, {
  Actions: FileActions,
  Content: FileContent,
  Media: FileMedia,
  Meta: FileMeta,
  Name: FileName,
  Root: FileRoot,
  Size: FileSize,
});

import type { FileInputProps as FileInputSharedProps } from "@pisagor/props";
import { fileInputRecipe, formControlGroupShellRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType, ref } from "vue";
import {
  InputGroupAddon,
  InputGroupButton,
  InputGroupText,
} from "../input-group/input-group-core";
import { useFormControlSurface } from "../surface/use-form-control-surface";

type FormControlVariant = "primary" | "secondary";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface FileInputProps extends FileInputSharedProps {
  accept?: string;
  /** Label for the browse button. */
  browseLabel?: string;
  capture?: "environment" | "user";
  class?: unknown;
  disabled?: boolean;
  id?: string;
  /** Marks the control invalid for styling and assistive tech. */
  invalid?: boolean;
  multiple?: boolean;
  name?: string;
  onChange?: (event: Event) => void;
  /** Called with accepted files when the selection changes. */
  onFilesChange?: (files: File[]) => void;
  /** Alias for `onFilesChange`; matches `FileUpload` callback naming. */
  onValueChange?: (files: File[]) => void;
  /** Text shown when no file is selected. */
  placeholder?: string;
  required?: boolean;
  size?: "lg" | "md" | "sm";
  /**
   * Visual shell variant. Defaults to `primary`.
   */
  variant?: FormControlVariant;
}
// #endregion

// #region Helpers
function getSelectedFiles(input: HTMLInputElement): File[] {
  return input.files ? Array.from(input.files) : [];
}

function formatFileLabel(files: File[]): string | undefined {
  if (files.length === 0) {
    return undefined;
  }

  if (files.length === 1) {
    return files[0]?.name;
  }

  return `${files.length} files selected`;
}
// #endregion

// #region Component
export const FileInput = defineComponent({
  inheritAttrs: false,
  name: "FileInput",
  props: {
    accept: { default: undefined, type: String },
    browseLabel: { default: "Choose file", type: String },
    capture: {
      default: undefined,
      type: String as PropType<FileInputProps["capture"]>,
    },
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    disabled: { default: undefined, type: Boolean },
    id: { default: undefined, type: String },
    invalid: { default: undefined, type: Boolean },
    multiple: { default: undefined, type: Boolean },
    name: { default: undefined, type: String },
    onChange: {
      default: undefined,
      type: Function as PropType<FileInputProps["onChange"]>,
    },
    onFilesChange: {
      default: undefined,
      type: Function as PropType<FileInputProps["onFilesChange"]>,
    },
    onValueChange: {
      default: undefined,
      type: Function as PropType<FileInputProps["onValueChange"]>,
    },
    placeholder: { default: "No file chosen", type: String },
    recipe: {
      default: fileInputRecipe,
      type: Function as PropType<typeof fileInputRecipe>,
    },
    required: { default: undefined, type: Boolean },
    size: { default: "md", type: String as PropType<FileInputProps["size"]> },
    variant: {
      default: undefined,
      type: String as PropType<FormControlVariant>,
    },
  },
  setup(props, { attrs }) {
    const surfaceVariant = useFormControlSurface();

    const inputRef = ref<HTMLInputElement | null>(null);
    const fileLabel = ref<string>();

    const openPicker = () => {
      inputRef.value?.click();
    };

    const handleChange = (event: Event) => {
      props.onChange?.(event);
      const files = getSelectedFiles(event.currentTarget as HTMLInputElement);
      props.onFilesChange?.(files);
      props.onValueChange?.(files);
      fileLabel.value = formatFileLabel(files);
    };

    return () => {
      const resolved = {
        surfaceVariant,
        variant: props.variant ?? ("primary" as FormControlVariant),
      };
      const shellArgs = {
        surfaceVariant: resolved.surfaceVariant,
        variant: resolved.variant,
      };
      const controlProps = { "data-variant": resolved.variant };
      const slots = props.recipe();

      return h(
        "div",
        {
          ...attrs,
          ...controlProps,
          class: cn(
            formControlGroupShellRecipe({
              class: slots.root(),
              size: props.size,
              ...shellArgs,
            }),
            props.class,
          ),
          "data-disabled": props.disabled || undefined,
          "data-part": "root",
          "data-scope": "file-input",
          "data-size": props.size,
          role: "group",
        },
        [
          h("input", {
            accept: props.accept,
            "aria-invalid": props.invalid || undefined,
            capture: props.capture,
            class: slots.control(),
            "data-invalid": props.invalid || undefined,
            "data-part": "control",
            "data-scope": "file-input",
            disabled: props.disabled,
            id: props.id,
            multiple: props.multiple,
            name: props.name,
            onChange: handleChange,
            ref: inputRef,
            required: props.required,
            type: "file",
          }),
          h(InputGroupAddon as ArkPart, { align: "inline-start" }, () =>
            h(
              InputGroupButton as ArkPart,
              { disabled: props.disabled, onClick: openPicker, type: "button" },
              () => props.browseLabel,
            ),
          ),
          h(
            InputGroupText as ArkPart,
            {
              class: slots.label(),
              onClick: props.disabled ? undefined : openPicker,
            },
            () => fileLabel.value ?? props.placeholder,
          ),
        ],
      );
    };
  },
});
// #endregion

