import { ark } from "@ark-ui/vue/factory";
import type { FrameProps as FrameRootSharedProps } from "@pisagor/props";
import { frameRecipe } from "@pisagor/recipes";
import { computed, defineComponent, h, type PropType } from "vue";
import {
  provideSurfaceContext,
  type SurfaceVariant,
  useSurface,
} from "../surface/surface";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface FrameRootProps extends FrameRootSharedProps {
  class?: unknown;
}
// #endregion

// #region Parts
export const FrameRoot = defineComponent({
  inheritAttrs: false,
  name: "FrameRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: frameRecipe,
      type: Function as PropType<typeof frameRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const parent = useSurface();

    provideSurfaceContext(
      computed(() => ({
        depth: parent ? parent.depth + 1 : 0,
        variant: "secondary" as SurfaceVariant,
      })),
    );

    return () => {
      const variantSlots = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
          "data-part": "root",
          "data-scope": "frame",
        },
        slots.default?.(),
      );
    };
  },
});

