import { ark } from "@ark-ui/vue/factory";
import type {
  MenuItemProps as MenuItemSharedProps,
  MenuProps as MenuRootSharedProps,
} from "@pisagor/props";
import {
  type MenuRecipeSlot,
  menuItemRecipe,
  menuRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType } from "vue";
import type { VariantClassNames } from "../../internal/types";

// #region Types
type MenuClassNames = VariantClassNames<MenuRecipeSlot>;

export interface MenuRootProps extends MenuRootSharedProps {
  classNames?: MenuClassNames;
}

export interface MenuItemProps extends MenuItemSharedProps {
  class?: unknown;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

// #region Parts
export const MenuRoot = defineComponent({
  inheritAttrs: false,
  name: "MenuRoot",
  props: {
    classNames: {
      default: undefined,
      type: Object as PropType<MenuClassNames>,
    },
    recipe: {
      default: menuRecipe,
      type: Function as PropType<typeof menuRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const slots$ = props.recipe();
      const ariaLabel = (attrs["aria-label"] as string | undefined) ?? "Menu";

      return h(
        ark.nav as ArkPart,
        {
          ...attrs,
          "aria-label": ariaLabel,
          class: slots$.base({ class: attrs.class as string | undefined }),
          "data-part": "root",
          "data-scope": "menu",
        },
        slots,
      );
    };
  },
});

export const MenuList = defineComponent({
  inheritAttrs: false,
  name: "MenuList",
  props: {
    classNames: {
      default: undefined,
      type: Object as PropType<MenuClassNames>,
    },
    recipe: {
      default: menuRecipe,
      type: Function as PropType<typeof menuRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const slots$ = props.recipe();

      return h(
        ark.ul as ArkPart,
        {
          ...attrs,
          class: slots$.list({
            class: cn(attrs.class, props.classNames?.list),
          }),
          "data-part": "list",
          "data-scope": "menu",
          role: "list",
        },
        slots,
      );
    };
  },
});

export const MenuGroup = defineComponent({
  inheritAttrs: false,
  name: "MenuGroup",
  props: {
    classNames: {
      default: undefined,
      type: Object as PropType<MenuClassNames>,
    },
    recipe: {
      default: menuRecipe,
      type: Function as PropType<typeof menuRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const slots$ = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: slots$.group({
            class: cn(attrs.class, props.classNames?.group),
          }),
          "data-part": "group",
          "data-scope": "menu",
          role: "group",
        },
        slots,
      );
    };
  },
});

export const MenuGroupLabel = defineComponent({
  inheritAttrs: false,
  name: "MenuGroupLabel",
  props: {
    classNames: {
      default: undefined,
      type: Object as PropType<MenuClassNames>,
    },
    recipe: {
      default: menuRecipe,
      type: Function as PropType<typeof menuRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const slots$ = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: slots$.groupLabel({
            class: cn(attrs.class, props.classNames?.groupLabel),
          }),
          "data-part": "group-label",
          "data-scope": "menu",
        },
        slots,
      );
    };
  },
});

export const MenuItem = defineComponent({
  inheritAttrs: false,
  name: "MenuItem",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<MenuClassNames>,
    },
    recipe: {
      default: menuItemRecipe,
      type: Function as PropType<typeof menuItemRecipe>,
    },
    type: { default: "button", type: String },
    variant: {
      default: "default",
      type: String as PropType<"default" | "destructive">,
    },
  },
  setup(props, { attrs, slots: children }) {
    return () => {
      const menuSlots = menuRecipe();

      return h(
        ark.li as ArkPart,
        {
          class: menuSlots.wrapper({ class: props.classNames?.wrapper }),
          "data-part": "item-wrapper",
          "data-scope": "menu",
          role: "none",
        },
        () =>
          h(
            ark.button as ArkPart,
            {
              ...attrs,
              class: cn(
                props.recipe({ variant: props.variant }),
                props.class,
                props.classNames?.item,
              ),
              "data-part": "item",
              "data-scope": "menu",
              "data-variant": props.variant,
              type: props.type,
            },
            children,
          ),
      );
    };
  },
});

export const MenuLink = defineComponent({
  inheritAttrs: false,
  name: "MenuLink",
  props: {
    active: { default: false, type: Boolean },
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<MenuClassNames>,
    },
    recipe: {
      default: menuRecipe,
      type: Function as PropType<typeof menuRecipe>,
    },
  },
  setup(props, { attrs, slots: children }) {
    return () => {
      const slots = props.recipe();

      return h(
        ark.li as ArkPart,
        {
          class: slots.wrapper({ class: props.classNames?.wrapper }),
          "data-part": "item-wrapper",
          "data-scope": "menu",
          role: "none",
        },
        () =>
          h(
            ark.a as ArkPart,
            {
              ...attrs,
              "aria-current": props.active ? "page" : undefined,
              class: slots.link({
                class: cn(props.class, props.classNames?.link),
              }),
              "data-active": props.active,
              "data-part": "link",
              "data-scope": "menu",
            },
            children,
          ),
      );
    };
  },
});

export const MenuSeparator = defineComponent({
  inheritAttrs: false,
  name: "MenuSeparator",
  props: {
    classNames: {
      default: undefined,
      type: Object as PropType<MenuClassNames>,
    },
    recipe: {
      default: menuRecipe,
      type: Function as PropType<typeof menuRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const slots$ = props.recipe();

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          "aria-hidden": true,
          class: slots$.separator({
            class: cn(attrs.class, props.classNames?.separator),
          }),
          "data-part": "separator",
          "data-scope": "menu",
          role: "separator",
        },
        slots,
      );
    };
  },
});

export const MenuShortcut = defineComponent({
  inheritAttrs: false,
  name: "MenuShortcut",
  props: {
    classNames: {
      default: undefined,
      type: Object as PropType<MenuClassNames>,
    },
    recipe: {
      default: menuRecipe,
      type: Function as PropType<typeof menuRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const slots$ = props.recipe();

      return h(
        ark.span as ArkPart,
        {
          ...attrs,
          class: slots$.shortcut({
            class: cn(attrs.class, props.classNames?.shortcut),
          }),
          "data-part": "shortcut",
          "data-scope": "menu",
        },
        slots,
      );
    };
  },
});
// #endregion

import {
  MenuGroup,
  MenuGroupLabel,
  MenuItem,
  MenuLink,
  MenuList,
  MenuRoot,
  MenuSeparator,
  MenuShortcut,
} from "./menu";

export type {
  MenuItemProps,
  MenuRootProps,
} from "./menu";

export const Menu = Object.assign(MenuRoot, {
  Group: MenuGroup,
  GroupLabel: MenuGroupLabel,
  Item: MenuItem,
  Link: MenuLink,
  List: MenuList,
  Root: MenuRoot,
  Separator: MenuSeparator,
  Shortcut: MenuShortcut,
});

