      type: Object as PropType<NavigationMenuClassNames>,
    },
    recipe: {
      default: navigationMenuRecipe,
      type: Function as PropType<typeof navigationMenuRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const slots$ = props.recipe();

      return h(
        ark.nav as ArkPart,
