import { NumberInput as NumberInputPrimitive } from "@ark-ui/vue/number-input";
import { PhMinus, PhPlus } from "@phosphor-icons/vue";
import type { NumberInputProps as NumberInputSharedProps } from "@pisagor/props";
import {
  type FormControlGroupShellVariantProps,
  formControlGroupShellRecipe,
  numberInputRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType } from "vue";
import { Button } from "../button/button";
import { FieldLabel } from "../field/field";
import { Input, type InputProps } from "../input/input";
import { InputClearButton } from "../input/input-clear-button";
import { useFormControlSurface } from "../surface/use-form-control-surface";

type FormControlVariant = "primary" | "secondary";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface NumberInputProps
  extends FormControlGroupShellVariantProps,
    NumberInputSharedProps {
  class?: unknown;
  clearable?: boolean;
  defaultValue?: string;
  disabled?: boolean;
  max?: number;
  min?: number;
  onValueChange?: (value: number) => void;
  placeholder?: string;
  readOnly?: boolean;
  step?: number;
  value?: string;
}

export interface NumberInputControlProps
  extends Pick<FormControlGroupShellVariantProps, "variant"> {
  class?: unknown;
  clearable?: boolean;
}
// #endregion

// #region Parts
export const NumberInputRoot = defineComponent({
  inheritAttrs: false,
  name: "NumberInputRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    clearable: { default: false, type: Boolean },
    defaultValue: { default: undefined, type: String },
    disabled: { default: undefined, type: Boolean },
    max: { default: undefined, type: Number },
    min: { default: undefined, type: Number },
    onValueChange: {
      default: undefined,
      type: Function as PropType<NumberInputProps["onValueChange"]>,
    },
    placeholder: { default: undefined, type: String },
    readOnly: { default: undefined, type: Boolean },
    recipe: {
      default: numberInputRecipe,
      type: Function as PropType<typeof numberInputRecipe>,
    },
    size: { default: "md", type: String as PropType<NumberInputProps["size"]> },
    step: { default: undefined, type: Number },
    value: { default: undefined, type: String },
    variant: {
      default: undefined,
      type: String as PropType<FormControlVariant>,
    },
  },
  setup(props, { attrs, slots }) {
    return () =>
      h(
        NumberInputPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: cn(props.recipe().base(), props.class),
          "data-size": props.size,
          defaultValue: props.defaultValue,
          disabled: props.disabled,
          max: props.max,
          min: props.min,
          modelValue: props.value,
          onValueChange: props.onValueChange
            ? (details: { value: string }) =>
                props.onValueChange?.(Number(details.value))
            : undefined,
          readOnly: props.readOnly,
          step: props.step,
        },
        () =>
          slots.default?.() ?? [
            h(
              NumberInputControl as ArkPart,
              { clearable: props.clearable, variant: props.variant },
              () => [
                h(NumberInputDecrementTrigger as ArkPart),
                h(NumberInputInput as ArkPart, {
                  placeholder: props.placeholder,
                  size: props.size,
                  variant: props.variant,
                }),
                h(NumberInputClearTrigger as ArkPart),
                h(NumberInputIncrementTrigger as ArkPart),
              ],
            ),
          ],
      );
  },
});

export const NumberInputControl = defineComponent({
  inheritAttrs: false,
  name: "NumberInputControl",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    clearable: { default: false, type: Boolean },
    recipe: {
      default: numberInputRecipe,
      type: Function as PropType<typeof numberInputRecipe>,
    },
    variant: {
      default: undefined,
      type: String as PropType<FormControlVariant>,
    },
  },
  setup(props, { attrs, slots }) {
    const surfaceVariant = useFormControlSurface();

    return () => {
      const resolved = {
        surfaceVariant,
        variant: props.variant ?? ("primary" as FormControlVariant),
      };
      const shellArgs = {
        surfaceVariant: resolved.surfaceVariant,
        variant: resolved.variant,
      };
      const controlProps = { "data-variant": resolved.variant };

      return h(
        NumberInputPrimitive.Control as ArkPart,
        {
          ...attrs,
          ...controlProps,
          class: cn(
            props.recipe().control(),
            formControlGroupShellRecipe({ size: "md", ...shellArgs }),
            props.class,
          ),
          "data-clearable": props.clearable || undefined,
        },
        slots,
      );
    };
  },
});

export const NumberInputClearTrigger = defineComponent({
  name: "NumberInputClearTrigger",
  props: {
    recipe: {
      default: numberInputRecipe,
      type: Function as PropType<typeof numberInputRecipe>,
    },
  },
  setup(props) {
    return () =>
      h(NumberInputPrimitive.Context as ArkPart, null, {
        default: (api: {
          setValue: (value: number) => void;
          value: string | undefined;
        }) => {
          const hasValue =
            api.value !== undefined &&
            api.value !== null &&
            String(api.value).length > 0;

          if (!hasValue) {
            return null;
          }

          return h(InputClearButton as ArkPart, {
            class: props.recipe().clearTrigger(),
            onClear: () => api.setValue(Number.NaN),
          });
        },
      });
  },
});

export const NumberInputDecrementTrigger = defineComponent({
  inheritAttrs: false,
  name: "NumberInputDecrementTrigger",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: numberInputRecipe,
      type: Function as PropType<typeof numberInputRecipe>,
    },
  },
  setup(props, { attrs }) {
    return () =>
      h(
        NumberInputPrimitive.DecrementTrigger as ArkPart,
        {
          ...attrs,
          asChild: true,
          class: cn(props.recipe().decrementTrigger(), props.class),
        },
        () =>
          h(
            Button as ArkPart,
            { "aria-label": "Decrement", variant: "ghost" },
            () => h(PhMinus, { "aria-hidden": true }),
          ),
      );
  },
});

export const NumberInputIncrementTrigger = defineComponent({
  inheritAttrs: false,
  name: "NumberInputIncrementTrigger",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: numberInputRecipe,
      type: Function as PropType<typeof numberInputRecipe>,
    },
  },
  setup(props, { attrs }) {
    return () =>
      h(
        NumberInputPrimitive.IncrementTrigger as ArkPart,
        {
          ...attrs,
          asChild: true,
          class: cn(props.recipe().incrementTrigger(), props.class),
        },
        () =>
          h(
            Button as ArkPart,
            { "aria-label": "Increment", variant: "ghost" },
            () => h(PhPlus, { "aria-hidden": true }),
          ),
      );
  },
});

export const NumberInputInput = defineComponent({
  inheritAttrs: false,
  name: "NumberInputInput",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<InputProps["classNames"]>,
    },
    placeholder: { default: undefined, type: String },
    recipe: {
      default: numberInputRecipe,
      type: Function as PropType<typeof numberInputRecipe>,
    },
    size: {
      default: undefined,
      type: String as PropType<NumberInputProps["size"]>,
    },
    variant: {
      default: undefined,
      type: String as PropType<FormControlVariant>,
    },
  },
  setup(props, { attrs }) {
    return () =>
      h(
        NumberInputPrimitive.Input as ArkPart,
        { asChild: true, ...attrs },
        () =>
          h(Input as ArkPart, {
            ...(attrs as object),
            class: cn(props.recipe().input(), props.class),
            classNames: props.classNames,
            placeholder: props.placeholder,
            size: props.size,
            variant: props.variant,
          }),
      );
  },
});

export const NumberInputScrubber = defineComponent({
  inheritAttrs: false,
  name: "NumberInputScrubber",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: numberInputRecipe,
      type: Function as PropType<typeof numberInputRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () =>
      h(
        NumberInputPrimitive.Scrubber as ArkPart,
        {
          ...attrs,
          asChild: true,
          class: cn(props.recipe().scrubber(), props.class),
        },
        () =>
          h(NumberInputPrimitive.Label as ArkPart, { asChild: true }, () =>
            h(FieldLabel as ArkPart, null, slots.default),
          ),
      );
  },
});
// #endregion

import {
  NumberInputClearTrigger,
  NumberInputControl,
  NumberInputDecrementTrigger,
  NumberInputIncrementTrigger,
  NumberInputInput,
  NumberInputRoot,
  NumberInputScrubber,
} from "./number-input";

export type { NumberInputControlProps, NumberInputProps } from "./number-input";

export const NumberInput = Object.assign(NumberInputRoot, {
  ClearTrigger: NumberInputClearTrigger,
  Control: NumberInputControl,
  DecrementTrigger: NumberInputDecrementTrigger,
  IncrementTrigger: NumberInputIncrementTrigger,
  Input: NumberInputInput,
  Scrubber: NumberInputScrubber,
});

import { ark } from "@ark-ui/vue/factory";
import {
  Pagination as PaginationPrimitive,
  usePaginationContext,
} from "@ark-ui/vue/pagination";
import { PhCaretLeft, PhCaretRight, PhDotsThree } from "@phosphor-icons/vue";
import type { PaginationProps as PaginationRootSharedProps } from "@pisagor/props";
import { buttonRecipe, paginationRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType } from "vue";
import { Button, type ButtonProps } from "../button";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface PaginationItemLinkProps extends ButtonProps {
  page?: "previous" | "next" | number;
}

export interface PaginationRootProps extends PaginationRootSharedProps {
  class?: unknown;
}
// #endregion

// #region Parts
export const PaginationRoot = defineComponent({
  inheritAttrs: false,
  name: "PaginationRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: paginationRecipe,
      type: Function as PropType<typeof paginationRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        PaginationPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: cn(props.class, attrs.class) }),
        },
        slots.default ??
          (() => [
            h(PaginationPrevTrigger),
            h(PaginationItems),
            h(PaginationNextTrigger),
          ]),
      );
    };
  },
});

export const PaginationPrevTrigger = defineComponent({
  inheritAttrs: false,
  name: "PaginationPrevTrigger",
  setup(_, { attrs, slots }) {
    return () =>
      h(
        PaginationPrimitive.PrevTrigger as ArkPart,
        { ...attrs, asChild: true },
        () =>
          h(Button as ArkPart, { variant: "ghost" }, () => [
            h(PhCaretLeft),
            slots.default?.() ?? "Previous",
          ]),
      );
  },
});

export const PaginationNextTrigger = defineComponent({
  inheritAttrs: false,
  name: "PaginationNextTrigger",
  setup(_, { attrs, slots }) {
    return () =>
      h(
        PaginationPrimitive.NextTrigger as ArkPart,
        { ...attrs, asChild: true },
        () =>
          h(Button as ArkPart, { variant: "ghost" }, () => [
            slots.default?.() ?? "Next",
            h(PhCaretRight),
          ]),
      );
  },
});

export const PaginationItem = defineComponent({
  inheritAttrs: false,
  name: "PaginationItem",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: paginationRecipe,
      type: Function as PropType<typeof paginationRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        PaginationPrimitive.Item as ArkPart,
        { ...attrs, asChild: true },
        () =>
          h(
            Button as ArkPart,
            {
              class: variantSlots.item({ class: cn(props.class, attrs.class) }),
              size: "icon-md",
              variant: "ghost",
            },
            slots,
          ),
      );
    };
  },
});

export const PaginationItems = defineComponent({
  inheritAttrs: false,
  name: "PaginationItems",
  setup(_, { attrs }) {
    return () =>
      h(
        PaginationPrimitive.Context as ArkPart,
        { ...attrs },
        {
          default: ({
            pages,
          }: {
            pages: Array<{ type: string; value?: number }>;
          }) =>
            pages.map((page, index) => {
              if (page.type === "page") {
                return h(
                  PaginationItem,
                  { key: page.value, type: "page", value: page.value },
                  () => page.value,
                );
              }

              const previousPage = [...pages.slice(0, index)]
                .reverse()
                .find(
                  (item: { type: string; value?: number }) =>
                    item.type === "page",
                );
              const nextPage = pages
                .slice(index + 1)
                .find(
                  (item: { type: string; value?: number }) =>
                    item.type === "page",
                );
              const ellipsisKey = `ellipsis-${previousPage?.value ?? "start"}-${nextPage?.value ?? "end"}`;

              return h(PaginationEllipsis, { index, key: ellipsisKey });
            }),
        },
      );
  },
});

export const PaginationItemLink = defineComponent({
  inheritAttrs: false,
  name: "PaginationItemLink",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    page: {
      default: undefined,
      type: [String, Number] as PropType<"previous" | "next" | number>,
    },
    size: { default: undefined, type: String as PropType<ButtonProps["size"]> },
    variant: {
      default: undefined,
      type: String as PropType<ButtonProps["variant"]>,
    },
  },
  setup(props, { attrs, slots }) {
    const pagination = usePaginationContext();

    return () => {
      const pageValue = () => {
        if (props.page === "previous") {
          return pagination.value.previousPage;
        }

        if (props.page === "next") {
          return pagination.value.nextPage;
        }

        return props.page;
      };

      const variant =
        props.variant ?? (typeof props.page === "number" ? "outline" : "ghost");

      return h(
        ark.a as ArkPart,
        {
          ...attrs,
          class: cn(
            buttonRecipe({ size: props.size, variant }).base(),
            props.class,
            attrs.class,
          ),
          href: `?page=${pageValue()}`,
        },
        slots,
      );
    };
  },
});

export const PaginationEllipsis = defineComponent({
  inheritAttrs: false,
  name: "PaginationEllipsis",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: paginationRecipe,
      type: Function as PropType<typeof paginationRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        PaginationPrimitive.Ellipsis as ArkPart,
        {
          ...attrs,
          class: variantSlots.ellipsis({ class: cn(props.class, attrs.class) }),
        },
        slots.default ?? (() => h(PhDotsThree)),
      );
    };
  },
});
// #endregion

import {
  PaginationEllipsis,
  PaginationItem,
  PaginationItemLink,
  PaginationItems,
  PaginationNextTrigger,
  PaginationPrevTrigger,
  PaginationRoot,
} from "./pagination";

export type {
  PaginationItemLinkProps,
  PaginationRootProps,
} from "./pagination";

export const Pagination = Object.assign(PaginationRoot, {
  Ellipsis: PaginationEllipsis,
  Item: PaginationItem,
  ItemLink: PaginationItemLink,
  Items: PaginationItems,
  NextTrigger: PaginationNextTrigger,
  PrevTrigger: PaginationPrevTrigger,
});

import { PasswordInput as PasswordInputPrimitive } from "@ark-ui/vue/password-input";
import { PhEye, PhEyeSlash, PhX } from "@phosphor-icons/vue";
import type { PasswordInputProps as PasswordInputSharedProps } from "@pisagor/props";
import { passwordInputRecipe } from "@pisagor/recipes";
import { defineComponent, h, type PropType } from "vue";
import {
  type ClearableChangeEvent,
  useClearableInput,
} from "../../hooks/use-clearable-input";
import { InputGroup } from "../input-group";
import type {
  InputGroupButtonProps,
  InputGroupProps,
} from "../input-group/input-group-core";

type ArkPart = Parameters<typeof h>[0];

type ClearableInputChangeHandler = (event: ClearableChangeEvent) => void;

// #region Types
export interface PasswordInputProps
  extends Pick<InputGroupProps, "size" | "variant">,
    PasswordInputSharedProps {
  class?: unknown;
  clearButtonProps?: InputGroupButtonProps;
  clearable?: boolean;
  defaultValue?: string;
  defaultVisible?: boolean;
  disabled?: boolean;
  indicatorProps?: Record<string, unknown>;
  invalid?: boolean;
  onChange?: ClearableInputChangeHandler;
  onValueChange?: (value: string) => void;
  onVisibilityChange?: (details: { visible: boolean }) => void;
  placeholder?: string;
  readOnly?: boolean;
  value?: string;
  visibilityTriggerProps?: Record<string, unknown>;
  visible?: boolean;
}
// #endregion

// #region Component
export const PasswordInput = defineComponent({
  inheritAttrs: false,
  name: "PasswordInput",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    clearable: { default: false, type: Boolean },
    clearButtonProps: {
      default: undefined,
      type: Object as PropType<InputGroupButtonProps>,
    },
    defaultValue: { default: undefined, type: String },
    defaultVisible: { default: undefined, type: Boolean },
    disabled: { default: undefined, type: Boolean },
    indicatorProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    invalid: { default: undefined, type: Boolean },
    onChange: {
      default: undefined,
      type: Function as PropType<PasswordInputProps["onChange"]>,
    },
    onValueChange: {
      default: undefined,
      type: Function as PropType<PasswordInputProps["onValueChange"]>,
    },
    onVisibilityChange: {
      default: undefined,
      type: Function as PropType<PasswordInputProps["onVisibilityChange"]>,
    },
    placeholder: { default: undefined, type: String },
    readOnly: { default: undefined, type: Boolean },
    recipe: {
      default: passwordInputRecipe,
      type: Function as PropType<typeof passwordInputRecipe>,
    },
    size: {
      default: "md",
      type: String as PropType<PasswordInputProps["size"]>,
    },
    value: { default: undefined, type: String },
    variant: {
      default: undefined,
      type: String as PropType<PasswordInputProps["variant"]>,
    },
    visibilityTriggerProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    visible: { default: undefined, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    const { canClear, handleChange, handleClear, inputRef } = useClearableInput(
      {
        clearable: () => props.clearable,
        defaultValue: props.defaultValue,
        disabled: () => props.disabled,
        onChange: props.onChange,
        onValueChange: props.onValueChange,
        readOnly: () => props.readOnly,
        value: () => props.value,
      },
    );

    return () => {
      const { onClick: onClearClick, ...restClearButtonProps } =
        props.clearButtonProps ?? {};
      const { fallback, ...restIndicatorProps } = props.indicatorProps ?? {};
      const variantSlots = props.recipe();

      return h(
        PasswordInputPrimitive.Root as ArkPart,
        {
          class: variantSlots.base({ class: props.class }),
          "data-size": props.size,
          defaultVisible: props.defaultVisible,
          invalid: props.invalid,
          onVisibilityChange: props.onVisibilityChange,
          visible: props.visible,
        },
        () =>
          h(PasswordInputPrimitive.Control as ArkPart, { asChild: true }, () =>
            h(
              InputGroup as ArkPart,
              {
                class: variantSlots.control(),
                "data-clearable": props.clearable || undefined,
                size: props.size,
                variant: props.variant,
              },
              () => [
                h(
                  PasswordInputPrimitive.Input as ArkPart,
                  {
                    asChild: true,
                    defaultValue: props.defaultValue,
                    disabled: props.disabled,
                    onInput: handleChange,
                    placeholder: props.placeholder,
                    readOnly: props.readOnly,
                    ref: inputRef,
                    value: props.value,
                    ...(attrs as object),
                  },
                  () => h(InputGroup.Input as ArkPart, { clearable: false }),
                ),
                canClear.value
                  ? h(
                      InputGroup.Addon as ArkPart,
                      { align: "inline-end", class: variantSlots.clearAddon() },
                      () =>
                        h(
                          InputGroup.Button as ArkPart,
                          {
                            ...restClearButtonProps,
                            "aria-label": "Clear",
                            "data-part": "clear-trigger",
                            "data-scope": "password-input",
                            onClick: (event: MouseEvent) => {
                              handleClear();
                              onClearClick?.(event);
                            },
                            size: "icon-xs",
                            type: "button",
                            variant: "ghost",
                          },
                          () => slots.clearButton?.() ?? h(PhX),
                        ),
                    )
                  : null,
                h(InputGroup.Addon as ArkPart, { align: "inline-end" }, () =>
                  h(
                    PasswordInputPrimitive.VisibilityTrigger as ArkPart,
                    {
                      asChild: true,
                      ...props.visibilityTriggerProps,
                    },
                    () =>
                      h(
                        InputGroup.Button as ArkPart,
                        {
                          "aria-label": "Toggle password visibility",
                          size: "icon-xs",
                          type: "button",
                          variant: "ghost",
                        },
                        () =>
                          h(
                            PasswordInputPrimitive.Indicator as ArkPart,
                            {
                              ...restIndicatorProps,
                            },
                            {
                              default: () => slots.indicator?.() ?? h(PhEye),
                              fallback: () => fallback ?? h(PhEyeSlash),
                            },
                          ),
                      ),
                  ),
                ),
              ],
            ),
          ),
      );
    };
  },
});
// #endregion

