import { Popover as PopoverPrimitive } from "@ark-ui/vue/popover";
import type { PopoverProps as PopoverContentSharedProps } from "@pisagor/props";
import { popoverRecipe } from "@pisagor/recipes";
import {
  type CSSProperties,
  defineComponent,
  h,
  type PropType,
  Teleport,
} from "vue";
import { renderIconCloseButton } from "../../internal/close-button";

// #region Types
export interface PopoverContentProps extends PopoverContentSharedProps {
  class?: unknown;
  showCloseButton?: boolean;
}

export interface PopoverHeaderProps {
  class?: unknown;
  description?: string;
  title?: string;
}

export interface PopoverProps {
  lazyMount?: boolean;
  modal?: boolean;
  unmountOnExit?: boolean;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

function popoverTeleport(
  content: ReturnType<typeof h> | ReturnType<typeof h>[],
) {
  return h(Teleport, { to: "body" }, () => content);
}

// #region Parts
export const PopoverRoot = defineComponent({
  inheritAttrs: false,
  name: "PopoverRoot",
  props: {
    lazyMount: { default: true, type: Boolean },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    return () =>
      h(
        PopoverPrimitive.Root as ArkPart,
        {
          ...attrs,
          lazyMount: props.lazyMount,
          unmountOnExit: props.unmountOnExit,
        },
        slots,
      );
  },
});

export const PopoverTrigger = defineComponent({
  inheritAttrs: false,
  name: "PopoverTrigger",
  setup(_, { attrs, slots }) {
    return () =>
      h(
        PopoverPrimitive.Trigger as ArkPart,
        {
          ...attrs,
        },
        slots,
      );
  },
});

export const PopoverAnchor = defineComponent({
  inheritAttrs: false,
  name: "PopoverAnchor",
  setup(_, { attrs, slots }) {
    return () => h(PopoverPrimitive.Anchor as ArkPart, { ...attrs }, slots);
  },
});

export const PopoverPositioner = defineComponent({
  inheritAttrs: false,
  name: "PopoverPositioner",
  setup(_, { attrs, slots }) {
    return () => h(PopoverPrimitive.Positioner as ArkPart, { ...attrs }, slots);
  },
});

export const PopoverContent = defineComponent({
  inheritAttrs: false,
  name: "PopoverContent",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: popoverRecipe,
      type: Function as PropType<typeof popoverRecipe>,
    },
    showCloseButton: { default: false, type: Boolean },
  },
  setup(props, { attrs, slots: children }) {
    return () => {
      const slots = props.recipe();

      return popoverTeleport(
        h(PopoverPositioner, null, () =>
          h(
            PopoverPrimitive.Content as ArkPart,
            {
              ...attrs,
              class: slots.base({ class: props.class }),
            },
            () => [
              children.default?.(),
              props.showCloseButton
                ? h(PopoverCloseTrigger, { asChild: true }, () =>
                    renderIconCloseButton(slots.close()),
                  )
                : null,
            ],
          ),
        ),
      );
    };
  },
});

export const PopoverHeader = defineComponent({
  inheritAttrs: false,
  name: "PopoverHeader",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    description: String,
    recipe: {
      default: popoverRecipe,
      type: Function as PropType<typeof popoverRecipe>,
    },
    title: String,
  },
  setup(props, { attrs, slots }) {
    return () => {
      const recipe = props.recipe();

      return h(
        "div",
        {
          ...attrs,
          class: recipe.header({ class: props.class }),
          "data-part": "header",
          "data-scope": "popover",
        },
        () => [
          props.title ? h(PopoverTitle, null, () => props.title) : null,
          props.description
            ? h(PopoverDescription, null, () => props.description)
            : null,
          slots.default?.(),
        ],
      );
    };
  },
});

export const PopoverTitle = defineComponent({
  inheritAttrs: false,
  name: "PopoverTitle",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: popoverRecipe,
      type: Function as PropType<typeof popoverRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const recipe = props.recipe();

      return h(
        PopoverPrimitive.Title as ArkPart,
        {
          ...attrs,
          class: recipe.title({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const PopoverDescription = defineComponent({
  inheritAttrs: false,
  name: "PopoverDescription",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: popoverRecipe,
      type: Function as PropType<typeof popoverRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const recipe = props.recipe();

      return h(
        PopoverPrimitive.Description as ArkPart,
        {
          ...attrs,
          class: recipe.description({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const PopoverBody = defineComponent({
  inheritAttrs: false,
  name: "PopoverBody",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: popoverRecipe,
      type: Function as PropType<typeof popoverRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const recipe = props.recipe();

      return h(
        "div",
        {
          ...attrs,
          class: recipe.body({ class: props.class }),
          "data-part": "body",
          "data-scope": "popover",
        },
        slots,
      );
    };
  },
});

export const PopoverFooter = defineComponent({
  inheritAttrs: false,
  name: "PopoverFooter",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: popoverRecipe,
      type: Function as PropType<typeof popoverRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const recipe = props.recipe();

      return h(
        "div",
        {
          ...attrs,
          class: recipe.footer({ class: props.class }),
          "data-part": "footer",
          "data-scope": "popover",
        },
        slots,
      );
    };
  },
});

export const PopoverCloseTrigger = defineComponent({
  inheritAttrs: false,
  name: "PopoverCloseTrigger",
  setup(_, { attrs, slots }) {
    return () =>
      h(PopoverPrimitive.CloseTrigger as ArkPart, { ...attrs }, slots);
  },
});

export const PopoverArrow = defineComponent({
  inheritAttrs: false,
  name: "PopoverArrow",
  props: {
    recipe: {
      default: popoverRecipe,
      type: Function as PropType<typeof popoverRecipe>,
    },
    style: { default: undefined, type: Object as PropType<CSSProperties> },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const recipe = props.recipe();

      return h(
        PopoverPrimitive.Arrow as ArkPart,
        {
          ...attrs,
          style: {
            "--arrow-background": "var(--popover)",
            "--arrow-size": "calc(1.5 * var(--spacing))",
            ...props.style,
          } as CSSProperties,
        },
        () => [
          h(PopoverPrimitive.ArrowTip as ArkPart, { class: recipe.arrowTip() }),
          slots.default?.(),
        ],
      );
    };
  },
});
// #endregion

export const Popover = Object.assign(PopoverRoot, {
  Anchor: PopoverAnchor,
  Arrow: PopoverArrow,
  Body: PopoverBody,
  CloseTrigger: PopoverCloseTrigger,
  Content: PopoverContent,
  Description: PopoverDescription,
  Footer: PopoverFooter,
  Header: PopoverHeader,
  Positioner: PopoverPositioner,
  Title: PopoverTitle,
  Trigger: PopoverTrigger,
});

export {
  Popover,
  type PopoverContentProps,
  type PopoverHeaderProps,
  type PopoverProps,
} from "./popover";

