import { ark } from "@ark-ui/vue/factory";
import {
  PhListBullets,
  PhListNumbers,
  PhTextB,
  PhTextItalic,
  PhTextStrikethrough,
} from "@phosphor-icons/vue";
import type { RichTextEditorProps as RichTextEditorRootSharedProps } from "@pisagor/props";
import {
  formControlShellRecipe,
  type RichTextEditorRecipe,
  richTextEditorRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import StarterKit from "@tiptap/starter-kit";
import { type Editor, EditorContent, useEditor } from "@tiptap/vue-3";
import {
  defineComponent,
  h,
  type PropType,
  shallowReactive,
  watch,
  watchEffect,
} from "vue";
import { useFormControlSurface } from "../components/surface/use-form-control-surface";
import { Toggle } from "../components/toggle/toggle";
import { VisuallyHidden } from "../components/visually-hidden/visually-hidden";
import type { ClassValue } from "../internal/types";
import { createContext } from "../internal/utils/create-context";

type FormControlVariant = "primary" | "secondary";

type ArkPart = Parameters<typeof h>[0];

// #region Types
interface RichTextEditorContextValue {
  editor: Editor | null;
  slots: RichTextEditorRecipe;
}

export interface RichTextEditorRootProps extends RichTextEditorRootSharedProps {
  "aria-label"?: string;
  /** Initial HTML content for uncontrolled usage. */
  defaultValue?: string;
  /** Whether the editor is disabled. */
  disabled?: boolean;
  id?: string;
  /** Marks the control as invalid for styling and assistive tech. */
  invalid?: boolean;
  /** Native form field name for a hidden input mirroring the HTML value. */
  name?: string;
  /** Called when the editor loses focus. */
  onBlur?: () => void;
  /** Called with HTML when the document changes. */
  onValueChange?: (value: string) => void;
  /** Whether the editor is read-only. */
  readOnly?: boolean;
  /** Controlled HTML content. */
  value?: string;
  /** Visual shell variant. Defaults to `primary`. */
  variant?: FormControlVariant;
  class?: unknown;
}

export interface RichTextEditorToolbarProps {
  class?: unknown;
}

export interface RichTextEditorContentProps {
  class?: unknown;
}
// #endregion

// #region Context
const [provideRichTextEditorContext, useRichTextEditorContext] =
  createContext("RichTextEditor")<RichTextEditorContextValue>();

/**
 * Access the TipTap editor instance from the nearest RichTextEditor root.
 */
export function useRichTextEditor() {
  return useRichTextEditorContext()?.editor ?? null;
}
// #endregion

const richTextEditorRootProps = {
  "aria-label": String,
  class: { type: [String, Object, Array] as PropType<ClassValue> },
  defaultValue: { default: undefined, type: String },
  disabled: { default: false, type: Boolean },
  id: String,
  invalid: { default: false, type: Boolean },
  name: String,
  onBlur: {
    default: undefined,
    type: Function as PropType<RichTextEditorRootProps["onBlur"]>,
  },
  onValueChange: {
    default: undefined,
    type: Function as PropType<RichTextEditorRootProps["onValueChange"]>,
  },
  readOnly: { default: false, type: Boolean },
  recipe: {
    default: richTextEditorRecipe,
    type: Function as PropType<typeof richTextEditorRecipe>,
  },
  value: { default: undefined, type: String },
  variant: {
    default: undefined,
    type: String as PropType<FormControlVariant | undefined>,
  },
};

// #region Parts
export const RichTextEditorRoot = defineComponent({
  inheritAttrs: false,
  name: "RichTextEditorRoot",
  props: richTextEditorRootProps,
  setup(props, { attrs, slots }) {
    const surfaceVariant = useFormControlSurface();

    const recipeSlots = props.recipe();

    const editor = useEditor({
      content: props.value ?? props.defaultValue ?? "<p></p>",
      editable: !(props.readOnly || props.disabled),
      editorProps: {
        attributes: {
          ...(props.id ? { id: props.id } : {}),
          "aria-invalid": props.invalid ? "true" : "false",
        },
      },
      extensions: [StarterKit],
      onBlur: () => {
        props.onBlur?.();
      },
      onUpdate: ({ editor: current }) => {
        props.onValueChange?.(current.getHTML());
      },
    });

    watch(
      () => props.value,
      (value) => {
        const current = editor.value;
        if (!current || value === undefined) {
          return;
        }

        const nextValue = value === "" ? "<p></p>" : value;
        const existing = current.getHTML();

        if (nextValue !== existing) {
          current.commands.setContent(nextValue, { emitUpdate: false });
        }
      },
    );

    watchEffect(() => {
      editor.value?.setEditable(!(props.readOnly || props.disabled));
    });

    watchEffect(() => {
      const current = editor.value;
      if (!current) {
        return;
      }

      current.setOptions({
        editorProps: {
          attributes: {
            ...(props.id ? { id: props.id } : {}),
            "aria-invalid": props.invalid ? "true" : "false",
          },
        },
      });
    });

    const contextValue = shallowReactive<RichTextEditorContextValue>({
      editor: null,
      slots: recipeSlots,
    });

    watchEffect(() => {
      contextValue.editor = editor.value ?? null;
    });

    provideRichTextEditorContext(contextValue);

    return () => {
      const resolved = {
        surfaceVariant,
        variant: props.variant ?? ("primary" as FormControlVariant),
      };
      const shellArgs = {
        surfaceVariant: resolved.surfaceVariant,
        variant: resolved.variant,
      };
      const controlProps = { "data-variant": resolved.variant };
      const resolvedAriaLabel =
        props["aria-label"] ?? (props.id ? undefined : "Rich text editor");

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          ...controlProps,
          "aria-disabled": props.disabled || undefined,
          "aria-invalid": props.invalid || undefined,
          "aria-label": resolvedAriaLabel,
          "aria-readonly": props.readOnly || undefined,
          class: cn(
            formControlShellRecipe({ ...shellArgs }),
            recipeSlots.base({ class: props.class }),
          ),
          "data-disabled": props.disabled ? "true" : undefined,
          "data-invalid": props.invalid ? "true" : undefined,
          "data-part": "root",
          "data-readonly": props.readOnly ? "true" : undefined,
          "data-scope": "rich-text-editor",
          role: "group",
        },
        () => [
          props.name
            ? h(VisuallyHidden as ArkPart, {}, () =>
                h("input", {
                  name: props.name,
                  readOnly: true,
                  tabIndex: -1,
                  type: "hidden",
                  value:
                    props.value ??
                    editor.value?.getHTML() ??
                    props.defaultValue ??
                    "",
                }),
              )
            : null,
          slots.default?.(),
        ],
      );
    };
  },
});

export const RichTextEditorToolbar = defineComponent({
  inheritAttrs: false,
  name: "RichTextEditorToolbar",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    const context = useRichTextEditorContext();

    return () => {
      const editor = context?.editor;
      const recipeSlots = context?.slots;

      if (!editor || !recipeSlots) {
        return null;
      }

      const activeMarks = {
        bold: editor.isActive("bold"),
        bulletList: editor.isActive("bulletList"),
        italic: editor.isActive("italic"),
        orderedList: editor.isActive("orderedList"),
        strike: editor.isActive("strike"),
      };

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: recipeSlots.toolbar({ class: props.class }),
          "data-part": "toolbar",
          "data-scope": "rich-text-editor",
        },
        () =>
          slots.default?.() ?? [
            h("div", { class: recipeSlots.inline() }, () => [
              h(
                Toggle as ArkPart,
                {
                  "aria-label": "Bold",
                  onPressedChange: () =>
                    editor.chain().focus().toggleBold().run(),
                  pressed: activeMarks.bold,
                  size: "sm",
                  variant: "ghost",
                },
                () => [
                  h(PhTextB),
                  h(VisuallyHidden as ArkPart, {}, () => "Bold"),
                ],
              ),
              h(
                Toggle as ArkPart,
                {
                  "aria-label": "Italic",
                  onPressedChange: () =>
                    editor.chain().focus().toggleItalic().run(),
                  pressed: activeMarks.italic,
                  size: "sm",
                  variant: "ghost",
                },
                () => [
                  h(PhTextItalic),
                  h(VisuallyHidden as ArkPart, {}, () => "Italic"),
                ],
              ),
              h(
                Toggle as ArkPart,
                {
                  "aria-label": "Strikethrough",
                  onPressedChange: () =>
                    editor.chain().focus().toggleStrike().run(),
                  pressed: activeMarks.strike,
                  size: "sm",
                  variant: "ghost",
                },
                () => [
                  h(PhTextStrikethrough),
                  h(VisuallyHidden as ArkPart, {}, () => "Strikethrough"),
                ],
              ),
              h(
                Toggle as ArkPart,
                {
                  "aria-label": "Bullet list",
                  onPressedChange: () =>
                    editor.chain().focus().toggleBulletList().run(),
                  pressed: activeMarks.bulletList,
                  size: "sm",
                  variant: "ghost",
                },
                () => [
                  h(PhListBullets),
                  h(VisuallyHidden as ArkPart, {}, () => "Bullet list"),
                ],
              ),
              h(
                Toggle as ArkPart,
                {
                  "aria-label": "Ordered list",
                  onPressedChange: () =>
                    editor.chain().focus().toggleOrderedList().run(),
                  pressed: activeMarks.orderedList,
                  size: "sm",
                  variant: "ghost",
                },
                () => [
                  h(PhListNumbers),
                  h(VisuallyHidden as ArkPart, {}, () => "Ordered list"),
                ],
              ),
            ]),
          ],
      );
    };
  },
});

export const RichTextEditorContent = defineComponent({
  inheritAttrs: false,
  name: "RichTextEditorContent",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs }) {
    const context = useRichTextEditorContext();

    return () => {
      const recipeSlots = context?.slots;

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: recipeSlots?.content({ class: props.class }),
          "data-part": "content",
          "data-scope": "rich-text-editor",
        },
        () => h(EditorContent as ArkPart, { editor: context?.editor }),
      );
    };
  },
});

export const RichTextEditorShorthand = defineComponent({
  inheritAttrs: false,
  name: "RichTextEditor",
  props: richTextEditorRootProps,
  setup(props, { attrs }) {
    return () =>
      h(RichTextEditorRoot as ArkPart, { ...attrs, ...props }, () => [
        h(RichTextEditorToolbar),
        h(RichTextEditorContent),
      ]);
  },
});
// #endregion

import {
  RichTextEditorContent,
  RichTextEditorRoot,
  RichTextEditorShorthand,
  RichTextEditorToolbar,
} from "./rich-text-editor";

export type {
  RichTextEditorContentProps,
  RichTextEditorRootProps,
  RichTextEditorToolbarProps,
} from "./rich-text-editor";
export { useRichTextEditor } from "./rich-text-editor";

export const RichTextEditor = Object.assign(RichTextEditorShorthand, {
  Content: RichTextEditorContent,
  Root: RichTextEditorRoot,
  Toolbar: RichTextEditorToolbar,
});

import { ScrollArea as ScrollAreaPrimitive } from "@ark-ui/vue/scroll-area";
import type { ScrollAreaProps as ScrollAreaSharedProps } from "@pisagor/props";
import { type ScrollAreaRecipeSlot, scrollAreaRecipe } from "@pisagor/recipes";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";
import type { VariantClassNames } from "../../internal/types";

// #region Types
export interface ScrollAreaProps extends ScrollAreaSharedProps {
  class?: unknown;
  scrollFade?: boolean;
  /**
   * Slot class names.
   *
   * @example
   * `{ base: "...", viewport: "...", thumb: "..." }`
   */
  classNames?: VariantClassNames<ScrollAreaRecipeSlot>;
  /** Extra props forwarded to the scroll area viewport element. */
  viewportProps?: Record<string, unknown>;
  /** Extra props forwarded to each scroll area scrollbar element. */
  scrollbarProps?: Record<string, unknown>;
  /** Extra props forwarded to each scroll area thumb element. */
  thumbProps?: Record<string, unknown>;
  children?: VNodeChild;
}

type ArkPart = Parameters<typeof h>[0];

// #region Component
export const ScrollArea = defineComponent({
  inheritAttrs: false,
  name: "ScrollArea",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<VariantClassNames<ScrollAreaRecipeSlot>>,
    },
    recipe: {
      default: scrollAreaRecipe,
      type: Function as PropType<typeof scrollAreaRecipe>,
    },
    scrollbarProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    scrollFade: { default: false, type: Boolean },
    thumbProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    viewportProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const slotsClasses = props.recipe({ scrollFade: props.scrollFade });

      return h(
        ScrollAreaPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: slotsClasses.base({ class: props.class }),
        },
        () => [
          h(
            ScrollAreaPrimitive.Viewport as ArkPart,
            {
              ...(props.viewportProps ?? {}),
              class: slotsClasses.viewport({
                class: props.classNames?.viewport,
              }),
            },
            () =>
              h(ScrollAreaPrimitive.Content as ArkPart, {}, () =>
                slots.default?.(),
              ),
          ),
          h(
            ScrollAreaPrimitive.Scrollbar as ArkPart,
            {
              ...(props.scrollbarProps ?? {}),
              class: slotsClasses.scrollbar({
                class: props.classNames?.scrollbar,
              }),
              orientation: "vertical",
            },
            () =>
              h(
                ScrollAreaPrimitive.Thumb as ArkPart,
                {
                  ...(props.thumbProps ?? {}),
                  class: slotsClasses.thumb({ class: props.classNames?.thumb }),
                },
                undefined,
              ),
          ),
          h(
            ScrollAreaPrimitive.Scrollbar as ArkPart,
            {
              ...(props.scrollbarProps ?? {}),
              class: slotsClasses.scrollbar({
                class: props.classNames?.scrollbar,
              }),
              orientation: "horizontal",
            },
            () =>
              h(
                ScrollAreaPrimitive.Thumb as ArkPart,
                {
                  ...(props.thumbProps ?? {}),
                  class: slotsClasses.thumb({ class: props.classNames?.thumb }),
                },
                undefined,
              ),
          ),
          h(ScrollAreaPrimitive.Corner as ArkPart, {}),
        ],
      );
    };
  },
});
// #endregion

import type { ScrollspyProps as ScrollspySharedProps } from "@pisagor/props";
import { scrollspyRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import {
  defineComponent,
  h,
  onMounted,
  onUnmounted,
  type PropType,
  ref,
} from "vue";

// #region Types
type ScrollTarget = HTMLElement | Document | null | undefined;

const SCROLLSPY_ANCHOR = "data-scrollspy-anchor";
const SCROLLSPY_OFFSET = "data-scrollspy-offset";
const SCROLLSPY_ANCHOR_SELECTOR = `[${SCROLLSPY_ANCHOR}]`;

export interface ScrollspyProps extends ScrollspySharedProps {
  class?: unknown;
  /**
   * Whether to update the URL hash when the active section changes.
   *
   * @defaultValue true
   *
   * @remarks
   * Updates `window.location.hash`, which affects browser history navigation.
   */
  history?: boolean;
  /**
   * Called when the active section changes.
   */
  onUpdate?: (id: string) => void;
  /**
   * Global pixel offset from the top when calculating active sections.
   *
   * @defaultValue 0
   */
  offset?: number;
  /**
   * Whether to use smooth scrolling when clicking on anchors.
   *
   * @defaultValue true
   */
  smooth?: boolean;
  /**
   * The scrollable container to monitor. Omit to spy on the window.
   *
   * @remarks
   * Pass a template ref (e.g. `const parentRef = ref<HTMLElement | null>(null)` bound via
   * `ref="parentRef"`). Vue auto-unwraps the ref when read in a template, so this prop always
   * receives the live element rather than the `Ref` wrapper.
   */
  targetRef?: ScrollTarget;
}
// #endregion

// #region Helpers
function resolveScrollElement(target: ScrollTarget): HTMLElement | null {
  if (target === document) {
    return document.documentElement;
  }

  if (!(target instanceof HTMLElement)) {
    return document.documentElement;
  }

  const viewport = target.querySelector(
    '[data-scope="scroll-area"][data-part="viewport"]',
  );
  if (viewport instanceof HTMLElement) {
    return viewport;
  }

  return target;
}

function resolveScrollTarget(target: ScrollTarget): HTMLElement | Window {
  if (target === document || !target) {
    return window;
  }

  if (target instanceof HTMLElement) {
    const viewport = target.querySelector(
      '[data-scope="scroll-area"][data-part="viewport"]',
    );
    if (viewport instanceof HTMLElement) {
      return viewport;
    }

    return target;
  }

  return window;
}

function getSectionScrollOffset(
  sectionElement: HTMLElement,
  scrollElement: HTMLElement,
): number {
  if (scrollElement === document.documentElement) {
    return sectionElement.getBoundingClientRect().top + window.scrollY;
  }

  const sectionRect = sectionElement.getBoundingClientRect();
  const scrollRect = scrollElement.getBoundingClientRect();

  return sectionRect.top - scrollRect.top + scrollElement.scrollTop;
}
// #endregion

// #region Component
export const Scrollspy = defineComponent({
  inheritAttrs: false,
  name: "PisagorScrollspy",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    history: {
      default: true,
      type: Boolean as PropType<ScrollspyProps["history"]>,
    },
    offset: { default: 0, type: Number as PropType<ScrollspyProps["offset"]> },
    onUpdate: {
      default: undefined,
      type: Function as PropType<ScrollspyProps["onUpdate"]>,
    },
    recipe: {
      default: scrollspyRecipe,
      type: Function as PropType<typeof scrollspyRecipe>,
    },
    smooth: {
      default: true,
      type: Boolean as PropType<ScrollspyProps["smooth"]>,
    },
    targetRef: {
      default: undefined,
      type: Object as PropType<ScrollspyProps["targetRef"]>,
    },
  },
  setup(props, { attrs, slots }) {
    const selfRef = ref<HTMLDivElement | null>(null);

    let anchorElements: Element[] = [];
    let prevId: string | null = null;
    let removeScrollListener: (() => void) | undefined;
    let initialTimeout: number | undefined;

    const setActiveSection = (sectionId: string | null, force = false) => {
      if (!sectionId) {
        return;
      }

      for (const item of anchorElements) {
        const id = item.getAttribute(SCROLLSPY_ANCHOR);
        if (id === sectionId) {
          item.setAttribute("data-active", "true");
        } else {
          item.removeAttribute("data-active");
        }
      }

      props.onUpdate?.(sectionId);

      if (props.history && (force || prevId !== sectionId)) {
        window.history.replaceState({}, "", `#${sectionId}`);
      }

      prevId = sectionId;
    };

    const handleScroll = () => {
      if (anchorElements.length === 0) {
        return;
      }

      const scrollElement = resolveScrollElement(props.targetRef);
      if (!scrollElement) {
        return;
      }

      const scrollTop =
        scrollElement === document.documentElement
          ? window.scrollY || document.documentElement.scrollTop
          : scrollElement.scrollTop;

      let activeIdx = 0;
      let minDelta = Number.POSITIVE_INFINITY;

      anchorElements.forEach((anchor, idx) => {
        const sectionId = anchor.getAttribute(SCROLLSPY_ANCHOR);
        if (!sectionId) {
          return;
        }

        const sectionElement = document.getElementById(sectionId);
        if (!sectionElement) {
          return;
        }

        let customOffset = props.offset;
        const dataOffset = anchor.getAttribute(SCROLLSPY_OFFSET);
        if (dataOffset) {
          customOffset = Number.parseInt(dataOffset, 10);
        }

        const sectionOffset = getSectionScrollOffset(
          sectionElement,
          scrollElement,
        );
        const delta = Math.abs(sectionOffset - customOffset - scrollTop);

        if (sectionOffset - customOffset <= scrollTop && delta < minDelta) {
          minDelta = delta;
          activeIdx = idx;
        }
      });

      const scrollHeight = scrollElement.scrollHeight;
      const clientHeight = scrollElement.clientHeight;

      if (scrollTop + clientHeight >= scrollHeight - 2) {
        activeIdx = anchorElements.length - 1;
      }

      const activeAnchor = anchorElements[activeIdx];
      const sectionId = activeAnchor?.getAttribute(SCROLLSPY_ANCHOR) ?? null;

      setActiveSection(sectionId);
    };

    const scrollTo = (anchorElement: HTMLElement) => (event?: Event) => {
      event?.preventDefault();

      const sectionId =
        anchorElement.getAttribute(SCROLLSPY_ANCHOR)?.replace("#", "") ?? null;
      if (!sectionId) {
        return;
      }

      const sectionElement = document.getElementById(sectionId);
      if (!sectionElement) {
        return;
      }

      const scrollToElement = resolveScrollTarget(props.targetRef);

      let customOffset = props.offset;
      const dataOffset = anchorElement.getAttribute(SCROLLSPY_OFFSET);
      if (dataOffset) {
        customOffset = Number.parseInt(dataOffset, 10);
      }

      const scrollElement =
        scrollToElement instanceof HTMLElement
          ? scrollToElement
          : document.documentElement;
      const sectionOffset = getSectionScrollOffset(
        sectionElement,
        scrollElement,
      );
      const scrollTop = sectionOffset - customOffset;

      scrollToElement.scrollTo({
        behavior: props.smooth ? "smooth" : "auto",
        left: 0,
        top: scrollTop,
      });

      setActiveSection(sectionId, true);
    };

    const scrollToHashSection = () => {
      const hash = CSS.escape(window.location.hash.replace("#", ""));

      if (!hash) {
        return;
      }

      const targetElement = document.querySelector(
        `[${SCROLLSPY_ANCHOR}="${hash}"]`,
      ) as HTMLElement | null;

      if (targetElement) {
        scrollTo(targetElement)();
      }
    };

    onMounted(() => {
      if (selfRef.value) {
        anchorElements = Array.from(
          selfRef.value.querySelectorAll(SCROLLSPY_ANCHOR_SELECTOR),
        );
      }

      const anchorListeners = anchorElements.map((item) => {
        const listener = scrollTo(item as HTMLElement);
        item.addEventListener("click", listener);
        return { item, listener };
      });

      const onScroll = (event: Event) => {
        const scrollTarget = props.targetRef ?? document;
        const scrollElement = resolveScrollTarget(scrollTarget);

        if (
          scrollElement === window ||
          (scrollElement instanceof HTMLElement &&
            scrollElement.contains(event.target as Node))
        ) {
          handleScroll();
        }
      };

      window.addEventListener("scroll", onScroll, true);

      initialTimeout = window.setTimeout(() => {
        scrollToHashSection();
        handleScroll();
      }, 100);

      removeScrollListener = () => {
        window.removeEventListener("scroll", onScroll, true);
        for (const { item, listener } of anchorListeners) {
          item.removeEventListener("click", listener);
        }
      };
    });

    onUnmounted(() => {
      removeScrollListener?.();
      window.clearTimeout(initialTimeout);
    });

    return () =>
      h(
        "div",
        {
          ...attrs,
          class: cn(props.recipe(), props.class),
          "data-part": "root",
          "data-scope": "scrollspy",
          ref: selfRef,
        },
        slots.default?.(),
      );
  },
});
// #endregion

