  },
});

export const SelectTrigger = defineComponent({
  inheritAttrs: false,
  name: "SelectTrigger",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    clearable: { default: false, type: Boolean },
    recipe: {
      default: selectRecipe,
      type: Function as PropType<typeof selectRecipe>,
    },
    size: { default: "md", type: String as PropType<SelectTriggerSize> },
    variant: {
      default: undefined,
      type: String as PropType<FormControlVariant | undefined>,
    },
  },
  setup(props, { attrs, slots }) {
    const surfaceVariant = useFormControlSurface();

    return () => {
      const resolved = {
        surfaceVariant,
        variant: props.variant ?? ("primary" as FormControlVariant),
      };
      const shellArgs = {
        surfaceVariant: resolved.surfaceVariant,
        variant: resolved.variant,
      };
      const controlProps = { "data-variant": resolved.variant };
      const styleSlots = props.recipe();

      return h(SelectPrimitive.Control as ArkPart, {}, () =>
        h(
          SelectPrimitive.Trigger as ArkPart,
          {
            ...attrs,
            ...controlProps,
            class: cn(
              formControlShellRecipe({ size: props.size, ...shellArgs }),
              styleSlots.trigger(),
              props.class,
              attrs.class,
            ),
            "data-size": props.size,
          },
          () => [
            slots.default?.(),
            h("div", { class: styleSlots.triggerActions() }, () => [
              props.clearable
                ? h(SelectClearTrigger as ArkPart, null, () =>
                    h(PhX, { "aria-hidden": true }),
                  )
                : null,
              h(SelectPrimitive.Indicator as ArkPart, {}, () =>
                h(PhCaretUpDown, { "aria-hidden": true }),
              ),
            ]),
          ],
        ),
      );
    };
  },
});

