import { PhSidebarSimple } from "@phosphor-icons/vue";
import type { SidebarProps as SidebarProviderSharedProps } from "@pisagor/props";
import { sidebarRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";

type ClassValue = Parameters<typeof cn>[0];

import {
  defineComponent,
  h,
  type PropType,
  reactive,
  ref,
  watchEffect,
} from "vue";
import { useIsMobile } from "../../hooks/use-is-mobile";
import { createContext } from "../../internal/utils/create-context";
import { Button } from "../button";
import { Sheet } from "../sheet";
import { Tooltip, type TooltipProps } from "../tooltip";

// #region Types
type SidebarState = "expanded" | "collapsed";

type SidebarPlacement = "left" | "right";
type SidebarVariant = "sidebar" | "floating" | "inset";
type SidebarCollapsible = "offcanvas" | "icon" | "none";

export interface SidebarProps {
  className?: string;
  collapsible?: SidebarCollapsible;
  placement?: SidebarPlacement;
  variant?: SidebarVariant;
}

export interface SidebarProviderProps
  extends Omit<SidebarProps, "className">,
    SidebarProviderSharedProps {}

interface SidebarContextValue {
  isMobile: boolean;
  open: boolean;
  openMobile: boolean;
  state: SidebarState;
  setOpen: (value: boolean | ((current: boolean) => boolean)) => void;
  setOpenMobile: (value: boolean) => void;
  toggleSidebar: () => void;
  placement: SidebarPlacement;
  collapsible: SidebarCollapsible;
}
// #endregion

// #region Context
const [provideSidebarContext, useSidebarContext] = createContext(
  "Sidebar",
)<SidebarContextValue>({ strict: false });

export const useSidebar = () => useSidebarContext();
// #endregion

// #region Helpers
const SIDEBAR_STORAGE_KEY = "sidebar_state";

type ArkPart = Parameters<typeof h>[0];
// #endregion

// #region Parts
export const SidebarProvider = defineComponent({
  inheritAttrs: false,
  name: "SidebarProvider",
  props: {
    className: {
      default: undefined,
      type: String as PropType<string | undefined>,
    },
    collapsible: {
      default: "offcanvas",
      type: String as PropType<SidebarCollapsible>,
    },
    defaultOpen: { default: true, type: Boolean },
    onOpenChange: {
      default: undefined,
      type: Function as PropType<(open: boolean) => void>,
    },
    open: { default: undefined, type: Boolean },
    placement: { default: "left", type: String as PropType<SidebarPlacement> },
    recipe: {
      default: sidebarRecipe,
      type: Function as PropType<typeof sidebarRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const isMobileRef = useIsMobile();
    const openMobile = ref(false);

    const internalOpen = ref<boolean>(props.defaultOpen);
    const open = ref<boolean>(props.open ?? internalOpen.value);

    watchEffect(() => {
      open.value = props.open ?? internalOpen.value;
    });

    const setOpen = (value: boolean | ((current: boolean) => boolean)) => {
      const next =
        typeof value === "function"
          ? (value as (current: boolean) => boolean)(open.value)
          : value;

      if (props.onOpenChange) {
        props.onOpenChange(next);
      } else {
        internalOpen.value = next;
      }

      try {
        localStorage.setItem(SIDEBAR_STORAGE_KEY, String(next));
      } catch {
        // Ignore storage errors in restricted environments.
      }
    };

    const setOpenMobile = (value: boolean) => {
      openMobile.value = value;
    };

    const toggleSidebar = () => {
      if (isMobileRef.value) {
        openMobile.value = !openMobile.value;
      } else {
        setOpen((current) => !current);
      }
    };

    const contextValue = reactive<SidebarContextValue>({
      collapsible: props.collapsible,
      isMobile: isMobileRef.value,
      open: open.value,
      openMobile: openMobile.value,
      placement: props.placement,
      setOpen: (value) => setOpen(value),
      setOpenMobile: (value) => setOpenMobile(value),
      state: open.value ? "expanded" : "collapsed",
      toggleSidebar,
    });

    watchEffect(() => {
      contextValue.isMobile = isMobileRef.value;
      contextValue.open = open.value;
      contextValue.openMobile = openMobile.value;
      contextValue.state = open.value ? "expanded" : "collapsed";
    });

    provideSidebarContext(contextValue);

    return () => {
      const variantSlots = props.recipe();

      return h(
        "div",
        {
          ...attrs,
          class: cn(
            variantSlots.wrapper(),
            props.className,
            (attrs as { class?: ClassValue }).class,
          ),
          "data-part": "wrapper",
          "data-scope": "sidebar",
          style: {
            "--sidebar-width": "16rem",
            "--sidebar-width-icon": "3rem",
            ...(((attrs as { style?: unknown }).style as
              | Record<string, unknown>
              | undefined) ?? {}),
          },
        },
        slots.default?.(),
      );
    };
  },
});

export const SidebarRoot = defineComponent({
  inheritAttrs: false,
  name: "SidebarRoot",
  props: {
    className: { default: undefined, type: String },
    collapsible: {
      default: "offcanvas",
      type: String as PropType<SidebarCollapsible>,
    },
    placement: { default: "left", type: String as PropType<SidebarPlacement> },
    recipe: {
      default: sidebarRecipe,
      type: Function as PropType<typeof sidebarRecipe>,
    },
    variant: { default: "sidebar", type: String as PropType<SidebarVariant> },
  },
  setup(props, { attrs, slots }) {
    const ctx = useSidebarContext();

    return () => {
      if (!ctx) return null;

      const variantSlots = props.recipe();
      const padded = props.variant === "floating" || props.variant === "inset";
      const layoutSlots = props.recipe({ padded, placement: props.placement });

      if (props.collapsible === "none") {
        return h(
          "aside",
          {
            ...attrs,
            class: cn(
              variantSlots.base(),
              props.className,
              (attrs as { class?: ClassValue }).class,
            ),
            "data-part": "root",
            "data-scope": "sidebar",
          },
          slots.default?.(),
        );
      }

      if (ctx.isMobile) {
        return h(
          Sheet,
          {
            onOpenChange: ({ open }: { open: boolean }) =>
              ctx.setOpenMobile(open),
            open: ctx.openMobile,
          },
          {
            default: () =>
              h(
                Sheet.Content as ArkPart,
                {
                  ...(attrs as object),
                  class: variantSlots.mobile(),
                  "data-mobile": "true",
                  "data-sidebar": "sidebar",
                  placement: props.placement === "left" ? "left" : "right",
                  style: { "--sidebar-width": "18rem" },
                },
                () => slots.default?.(),
              ),
          },
        );
      }

      return h(
        "aside",
        {
          ...attrs,
          class: cn(
            variantSlots.peer(),
            props.className,
            (attrs as { class?: ClassValue }).class,
          ),
          "data-collapsible":
            ctx.state === "collapsed" ? props.collapsible : "",
          "data-part": "root",
          "data-placement": props.placement,
          "data-scope": "sidebar",
          "data-state": ctx.state,
          "data-variant": props.variant,
        },
        () => [
          h("div", {
            class: layoutSlots.gap(),
            "data-part": "gap",
            "data-scope": "sidebar",
          }),
          h(
            "div",
            {
              class: cn(
                layoutSlots.container(),
                props.className,
                (attrs as { class?: ClassValue }).class,
              ),
              "data-part": "container",
              "data-scope": "sidebar",
            },
            () =>
              h(
                "div",
                {
                  class: variantSlots.inner(),
                  "data-part": "inner",
                  "data-scope": "sidebar",
                  "data-sidebar": "sidebar",
                },
                slots.default?.(),
              ),
          ),
        ],
      );
    };
  },
});

