export const SidebarMenuButton = defineComponent({
  inheritAttrs: false,
  name: "SidebarMenuButton",
  props: {
    className: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    isActive: { default: false, type: Boolean },
    recipe: {
      default: sidebarRecipe,
      type: Function as PropType<typeof sidebarRecipe>,
    },
    size: { default: undefined, type: String },
    tooltip: {
      default: undefined,
      type: [String, Object] as PropType<
        string | Omit<TooltipProps, "children">
      >,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      const button = h(
        Button as ArkPart,
        {
          ...(attrs as object),
          class: cn(
            variantSlots.menuButton(),
            props.className,
            (attrs as { class?: ClassValue }).class,
          ),
          clickEffect: false,
          "data-active": props.isActive,
          "data-part": "menu-button",
          "data-scope": "sidebar",
          "data-size": props.size ?? "md",
          onClick: (event: MouseEvent) =>
            (attrs as { onClick?: (event: MouseEvent) => unknown }).onClick?.(
              event,
            ),
          size: (props.size ??
            (attrs as { size?: string }).size ??
            "md") as string,
          variant: "ghost",
        },
        () => slots.default?.(),
      );

      if (!props.tooltip) return button;

      const tooltipArgs =
        typeof props.tooltip === "string"
          ? { content: props.tooltip }
          : props.tooltip;
      return h(
        Tooltip as ArkPart,
        { ...tooltipArgs, positioning: { placement: "right" } },
        () => button,
      );
    };
  },
});

