import {
  createToaster,
  Toaster as ToasterPrimitive,
  Toast as ToastPrimitive,
} from "@ark-ui/vue/toast";
import {
  PhCheckCircle,
  PhInfo,
  PhWarning,
  PhWarningCircle,
  PhX,
} from "@phosphor-icons/vue";
import type {
  ToastProps as ToasterSharedProps,
  ToastItemProps as ToastItemSharedProps,
} from "@pisagor/props";
import {
  type ToastItemRecipeSlot,
  toastItemRecipe,
  toastRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";

type ClassValue = Parameters<typeof cn>[0];

import { defineComponent, h, type PropType, Teleport } from "vue";
import type { VariantClassNames } from "../../internal/types";
import { Button } from "../button";
import { Spinner } from "../spinner";

// #region Types
type ToastItemClassNames = VariantClassNames<ToastItemRecipeSlot>;

type ToastType = "error" | "info" | "loading" | "success" | "warning";

type ToastAction = {
  label: string;
  onClick: () => void;
};

type ToastData = {
  type?: ToastType;
  title: string;
  description?: string;
  closable?: boolean;
  action?: ToastAction;
};

export interface ToasterProps extends ToasterSharedProps {
  toaster?: unknown;
  class?: ClassValue;
  style?: Record<string, unknown>;
}

export interface ToastItemProps extends ToastItemSharedProps {
  toast: ToastData;
  class?: ClassValue;
  classNames?: ToastItemClassNames;
  iconProps?: Record<string, unknown>;
  titleProps?: Record<string, unknown>;
  descriptionProps?: Record<string, unknown>;
  actionsProps?: Record<string, unknown>;
  actionTriggerProps?: Record<string, unknown>;
  closeTriggerProps?: Record<string, unknown>;
}
// #endregion

// #region Constants
export const toast = createToaster({
  max: 3,
  overlap: true,
  placement: "bottom-end",
});

const TOAST_ICONS = {
  error: h(PhWarningCircle),
  info: h(PhInfo),
  loading: h(Spinner),
  success: h(PhCheckCircle),
  warning: h(PhWarning),
} as const;
// #endregion

// #region Parts
type ArkPart = Parameters<typeof h>[0];

export const ToasterRoot = defineComponent({
  inheritAttrs: false,
  name: "ToasterRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    recipe: {
      default: toastRecipe,
      type: Function as PropType<typeof toastRecipe>,
    },
    style: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    toaster: { default: undefined, type: Object as PropType<unknown> },
  },
  setup(props, { attrs }) {
    return () =>
      h(Teleport, { to: "body" }, () =>
        h(
          ToasterPrimitive as ArkPart,
          {
            ...attrs,
            class: cn(props.recipe(), props.class),
            style: { "--width": "356px", ...(props.style ?? {}) } as Record<
              string,
              unknown
            >,
            toaster: props.toaster ?? toast,
          },
          {
            default: ({ toastItem }: { toastItem: ToastData }) =>
              h(ToastItem, { toast: toastItem }),
          },
        ),
      );
  },
});

export const ToastItem = defineComponent({
  inheritAttrs: false,
  name: "ToastItem",
  props: {
    actionsProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    actionTriggerProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<ToastItemClassNames>,
    },
    closeTriggerProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    descriptionProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    iconProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    recipe: {
      default: toastItemRecipe,
      type: Function as PropType<typeof toastItemRecipe>,
    },
    titleProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    toast: { required: true, type: Object as PropType<ToastData> },
  },
  setup(props, { attrs }) {
    return () => {
      const slots = props.recipe();

      const toastData = props.toast;
      const toastAction = toastData.action;
      const icon = toastData.type ? TOAST_ICONS[toastData.type] : null;

      const isExplicitClosable = toastData.closable === false;

      return h(
        ToastPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: slots.base({ class: props.class }),
        },
        () => [
          h(
            "div",
            {
              class: slots.content({ class: props.classNames?.content }),
              "data-part": "content",
              "data-scope": "toast",
            },
            () => [
              h(
                "div",
                {
                  ...(props.iconProps ?? {}),
                  class: slots.icon({ class: props.classNames?.icon }),
                  "data-part": "icon",
                  "data-scope": "toast",
                },
                () => icon,
              ),
              h(
                "div",
                { class: slots.body({ class: props.classNames?.body }) },
                () => [
                  h(
                    ToastPrimitive.Title as ArkPart,
                    {
                      ...(props.titleProps ?? {}),
                      class: slots.title({
                        class: cn(
                          props.classNames?.title,
                          (
                            props.titleProps as
                              | { class?: ClassValue }
                              | undefined
                          )?.class,
                        ),
                      }),
                    },
                    () => toastData.title,
                  ),
                  toastData.description
                    ? h(
                        ToastPrimitive.Description as ArkPart,
                        {
                          ...(props.descriptionProps ?? {}),
                          class: slots.description({
                            class: cn(
                              props.classNames?.description,
                              (
                                props.descriptionProps as
                                  | { class?: ClassValue }
                                  | undefined
                              )?.class,
                            ),
                          }),
                        },
                        () => toastData.description,
                      )
                    : null,
                ],
              ),
            ],
          ),
          h(
            "div",
            {
              ...(props.actionsProps ?? {}),
              class: slots.actions({ class: props.classNames?.actions }),
              "data-part": "actions",
              "data-scope": "toast",
            },
            () => [
              toastAction
                ? h(
                    ToastPrimitive.ActionTrigger as ArkPart,
                    {
                      ...(props.actionTriggerProps ?? {}),
                      asChild: true,
                      onClick: toastAction.onClick,
                    },
                    () =>
                      h(
                        Button as ArkPart,
                        { size: "sm", variant: "secondary" },
                        () => toastAction.label,
                      ),
                  )
                : null,
              !isExplicitClosable
                ? h(
                    ToastPrimitive.CloseTrigger as ArkPart,
                    {
                      ...(props.closeTriggerProps ?? {}),
                      asChild: true,
                    },
                    () =>
                      h(
                        Button as ArkPart,
                        {
                          "aria-label": "Close",
                          class: slots.close({
                            class: props.classNames?.close,
                          }),
                          size: "icon-xs",
                          variant: "ghost",
                        },
                        () => h(PhX, { "aria-hidden": true }),
                      ),
                  )
                : null,
            ],
          ),
        ],
      );
    };
  },
});
// #endregion

import { ToasterRoot, ToastItem, toast } from "./toast";

export type { ToasterProps, ToastItemProps } from "./toast";

export { toast };

export const Toaster = Object.assign(ToasterRoot, {
  Item: ToastItem,
});

import { Toggle as TogglePrimitive } from "@ark-ui/vue/toggle";
import type { ToggleProps as ToggleSharedProps } from "@pisagor/props";
import {
  type ButtonVariantProps,
  buttonRecipe,
  type ToggleVariantProps,
  toggleRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType } from "vue";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface ToggleProps extends ToggleSharedProps {
  class?: unknown;
}
// #endregion

// #region Component
export const Toggle = defineComponent({
  emits: {
    pressedChange: (_pressed: boolean) => true,
    valueChange: (_value: boolean) => true,
  },
  inheritAttrs: false,
  name: "PisagorToggle",
  props: {
    buttonRecipe: {
      default: buttonRecipe,
      type: Function as PropType<typeof buttonRecipe>,
    },
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    disabled: { default: false, type: Boolean },
    recipe: {
      default: toggleRecipe,
      type: Function as PropType<typeof toggleRecipe>,
    },
    size: {
      default: "md",
      type: String as PropType<ToggleVariantProps["size"]>,
    },
    variant: {
      default: "ghost",
      type: String as PropType<
        Extract<ButtonVariantProps["variant"], "outline" | "ghost">
      >,
    },
  },
  setup(props, { attrs, emit, slots }) {
    return () =>
      h(
        TogglePrimitive.Root as ArkPart,
        {
          ...attrs,
          class: cn(
            props
              .buttonRecipe({ clickEffect: false, variant: props.variant })
              .base(),
            props.recipe({ size: props.size }),
            props.class,
          ),
          disabled: props.disabled,
          onPressedChange: (pressed: boolean) => {
            emit("pressedChange", pressed);
            emit("valueChange", pressed);
          },
        },
        slots,
      );
  },
});
// #endregion

import { ToggleGroup as ToggleGroupPrimitive } from "@ark-ui/vue/toggle-group";
import type { ToggleGroupProps as ToggleGroupRootSharedProps } from "@pisagor/props";
import { type ToggleGroupRecipe, toggleGroupRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";
import { createContext } from "../../internal/utils/create-context";
import { Toggle } from "../toggle";

export type ToggleGroupVariant = "ghost" | "outline";
export type ToggleGroupSize = "lg" | "md" | "sm";

interface ToggleGroupContextValue {
  size: ToggleGroupSize;
  slots: ToggleGroupRecipe;
  spacing: number;
  variant: ToggleGroupVariant;
}

export interface ToggleGroupRootProps extends ToggleGroupRootSharedProps {
  class?: unknown;
  defaultValue?: string[];
  disabled?: boolean;
  multiple?: boolean;
  orientation?: "horizontal" | "vertical";
  onValueChange?: (value: string | string[]) => void;
  spacing?: number;
  variant?: ToggleGroupVariant;
  size?: ToggleGroupSize;
  value?: string[];
}

export interface ToggleGroupPresetItem {
  value: string;
  disabled?: boolean;
  children: VNodeChild;
}

export interface ToggleGroupItemProps {
  class?: unknown;
  disabled?: boolean;
  value: string;
}

type ArkPart = Parameters<typeof h>[0];

const [ToggleGroupContextProvider, useToggleGroupContext] = createContext(
  "ToggleGroup",
)<ToggleGroupContextValue>({ strict: false });

export const ToggleGroupRoot = defineComponent({
  inheritAttrs: false,
  name: "ToggleGroupRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    defaultValue: {
      default: undefined,
      type: Array as PropType<string[] | undefined>,
    },
    disabled: { default: undefined, type: Boolean },
    multiple: { default: true, type: Boolean },
    onValueChange: {
      default: undefined,
      type: Function as PropType<ToggleGroupRootProps["onValueChange"]>,
    },
    orientation: {
      default: "horizontal",
      type: String as PropType<"horizontal" | "vertical">,
    },
    recipe: {
      default: toggleGroupRecipe,
      type: Function as PropType<typeof toggleGroupRecipe>,
    },
    size: { default: "md", type: String as PropType<ToggleGroupSize> },
    spacing: { default: 0, type: Number },
    value: {
      default: undefined,
      type: Array as PropType<string[] | undefined>,
    },
    variant: { default: "ghost", type: String as PropType<ToggleGroupVariant> },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe({ orientation: props.orientation });

      ToggleGroupContextProvider({
        size: props.size,
        slots: variantSlots,
        spacing: props.spacing,
        variant: props.variant,
      });

      return h(
        ToggleGroupPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.base(), props.class),
          defaultValue: props.defaultValue,
          modelValue: props.value,
          multiple: props.multiple,
          onValueChange: props.onValueChange
            ? (details: { value: string[] }) => {
                const nextValue = props.multiple
                  ? details.value
                  : (details.value[0] ?? "");
                return props.onValueChange?.(nextValue);
              }
            : undefined,
          orientation: props.orientation,
          style: {
            ...(attrs as object),
            ...(typeof (props as unknown as { style?: unknown }).style ===
            "object"
              ? (((props as unknown as { style: Record<string, unknown> })
                  .style ?? {}) as object)
              : {}),
            "--gap": props.spacing,
          } as unknown as Record<string, unknown>,
        },
        slots,
      );
    };
  },
});

export const ToggleGroupItem = defineComponent({
  inheritAttrs: false,
  name: "ToggleGroupItem",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    disabled: { default: undefined, type: Boolean },
    recipe: {
      default: toggleGroupRecipe,
      type: Function as PropType<typeof toggleGroupRecipe>,
    },
    value: { required: true, type: String },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const ctx = useToggleGroupContext();

      return h(
        ToggleGroupPrimitive.Item as ArkPart,
        {
          ...attrs,
          asChild: true,
          disabled: props.disabled,
          value: props.value,
        },
        () =>
          h(
            Toggle as ArkPart,
            {
              ...attrs,
              class: cn(
                ctx?.slots.item() ?? props.recipe().item(),
                props.class,
              ),
              "data-spacing": ctx?.spacing ?? 0,
              "data-variant": ctx?.variant ?? "ghost",
              disabled: props.disabled,
              size: ctx?.size ?? "md",
              variant: ctx?.variant ?? "ghost",
            },
            () => slots.default?.(),
          ),
      );
    };
  },
});

export const ToggleGroupShorthand = defineComponent({
  inheritAttrs: false,
  name: "ToggleGroup",
  props: {
    defaultValue: {
      default: undefined,
      type: Array as PropType<string[] | undefined>,
    },
    disabled: { default: undefined, type: Boolean },
    items: {
      default: undefined,
      type: Array as PropType<ToggleGroupPresetItem[] | undefined>,
    },
    multiple: { default: true, type: Boolean },
    onValueChange: {
      default: undefined,
      type: Function as PropType<ToggleGroupRootProps["onValueChange"]>,
    },
    orientation: {
      default: "horizontal",
      type: String as PropType<"horizontal" | "vertical">,
    },
    size: { default: "md", type: String as PropType<ToggleGroupSize> },
    spacing: { default: 0, type: Number },
    value: {
      default: undefined,
      type: Array as PropType<string[] | undefined>,
    },
    variant: { default: "ghost", type: String as PropType<ToggleGroupVariant> },
  },
  setup(props, { attrs }) {
    return () =>
      h(
        ToggleGroupRoot as ArkPart,
        {
          ...(attrs as object),
          defaultValue: props.defaultValue,
          disabled: props.disabled,
          multiple: props.multiple,
          onValueChange: props.onValueChange,
          orientation: props.orientation,
          size: props.size,
          spacing: props.spacing,
          value: props.value,
          variant: props.variant,
        },
        () =>
          props.items?.map((item) =>
            h(
              ToggleGroupItem as ArkPart,
              { disabled: item.disabled, key: item.value, value: item.value },
              () => item.children,
            ),
          ) ?? [],
      );
  },
});

import {
  ToggleGroupItem,
  ToggleGroupRoot,
  ToggleGroupShorthand,
} from "./toggle-group";

export type {
  ToggleGroupItemProps,
  ToggleGroupPresetItem,
  ToggleGroupRootProps,
  ToggleGroupSize,
  ToggleGroupVariant,
} from "./toggle-group";

export const ToggleGroup = Object.assign(ToggleGroupShorthand, {
  Item: ToggleGroupItem,
  Root: ToggleGroupRoot,
});

