import { ark } from "@ark-ui/vue/factory";
import type { ToolbarProps as ToolbarSharedProps } from "@pisagor/props";
import { type ToolbarRecipeSlot, toolbarRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";
import type { VariantClassNames } from "../../internal/types";

type ToolbarClassNames = VariantClassNames<ToolbarRecipeSlot>;

// #region Types
export interface ToolbarProps extends ToolbarSharedProps {
  class?: unknown;
  classNames?: ToolbarClassNames;
  title?: VNodeChild;
  description?: VNodeChild;
  actions?: VNodeChild;
  titleProps?: Record<string, unknown>;
  descriptionProps?: Record<string, unknown>;
  actionsProps?: Record<string, unknown>;
}

type ArkPart = Parameters<typeof h>[0];

// #region Parts
export const ToolbarRoot = defineComponent({
  inheritAttrs: false,
  name: "ToolbarRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<ToolbarClassNames>,
    },
    recipe: {
      default: toolbarRecipe,
      type: Function as PropType<typeof toolbarRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () =>
      h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: props.recipe().base({ class: props.class }),
          "data-part": "root",
          "data-scope": "toolbar",
        },
        slots,
      );
  },
});

export const ToolbarHeading = defineComponent({
  inheritAttrs: false,
  name: "ToolbarHeading",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<ToolbarClassNames>,
    },
    recipe: {
      default: toolbarRecipe,
      type: Function as PropType<typeof toolbarRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const slotsClasses = props.recipe();

    return () =>
      h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: slotsClasses.heading({
            class: cn(props.class, props.classNames?.heading),
          }),
          "data-part": "heading",
          "data-scope": "toolbar",
        },
        slots,
      );
  },
});

export const ToolbarTitle = defineComponent({
  inheritAttrs: false,
  name: "ToolbarTitle",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<ToolbarClassNames>,
    },
    recipe: {
      default: toolbarRecipe,
      type: Function as PropType<typeof toolbarRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const slotsClasses = props.recipe();

    return () =>
      h(
        ark.h2 as ArkPart,
        {
          ...attrs,
          class: slotsClasses.title({
            class: cn(props.class, props.classNames?.title),
          }),
          "data-part": "title",
          "data-scope": "toolbar",
        },
        slots,
      );
  },
});

export const ToolbarDescription = defineComponent({
  inheritAttrs: false,
  name: "ToolbarDescription",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<ToolbarClassNames>,
    },
    recipe: {
      default: toolbarRecipe,
      type: Function as PropType<typeof toolbarRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const slotsClasses = props.recipe();

    return () =>
      h(
        ark.p as ArkPart,
        {
          ...attrs,
          class: slotsClasses.description({
            class: cn(props.class, props.classNames?.description),
          }),
          "data-part": "description",
          "data-scope": "toolbar",
        },
        slots,
      );
  },
});

export const ToolbarActions = defineComponent({
  inheritAttrs: false,
  name: "ToolbarActions",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<ToolbarClassNames>,
    },
    recipe: {
      default: toolbarRecipe,
      type: Function as PropType<typeof toolbarRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const slotsClasses = props.recipe();

    return () =>
      h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: slotsClasses.actions({
            class: cn(props.class, props.classNames?.actions),
          }),
          "data-part": "actions",
          "data-scope": "toolbar",
        },
        slots,
      );
  },
});

export const ToolbarShorthand = defineComponent({
  inheritAttrs: false,
  name: "ToolbarShorthand",
  props: {
    actions: {
      default: undefined,
      type: [String, Object, Array, Function] as PropType<VNodeChild>,
    },
    actionsProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<ToolbarClassNames>,
    },
    description: {
      default: undefined,
      type: [String, Object, Array, Function] as PropType<VNodeChild>,
    },
    descriptionProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    title: {
      default: undefined,
      type: [String, Object, Array, Function] as PropType<VNodeChild>,
    },
    titleProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
  },
  setup(props, { attrs }) {
    return () => {
      const hasHeading =
        props.title !== undefined || props.description !== undefined;

      const nodes: VNodeChild[] = [];

      if (hasHeading) {
        nodes.push(
          h(ToolbarHeading, null, () => [
            props.title !== undefined
              ? h(ToolbarTitle, props.titleProps, () => props.title)
              : null,
            props.description !== undefined
              ? h(
                  ToolbarDescription,
                  props.descriptionProps,
                  () => props.description,
                )
              : null,
          ]),
        );
      }

      if (props.actions !== undefined) {
        nodes.push(h(ToolbarActions, props.actionsProps, () => props.actions));
      }

      return h(
        ToolbarRoot,
        {
          ...attrs,
          class: props.class,
          classNames: props.classNames,
        },
        () => nodes,
      );
    };
  },
});
// #endregion

import {
  ToolbarActions,
  ToolbarDescription,
  ToolbarHeading,
  ToolbarRoot,
  ToolbarShorthand,
  ToolbarTitle,
} from "./toolbar";

export type { ToolbarProps } from "./toolbar";

export const Toolbar = Object.assign(ToolbarShorthand, {
  Actions: ToolbarActions,
  Description: ToolbarDescription,
  Heading: ToolbarHeading,
  Root: ToolbarRoot,
  Title: ToolbarTitle,
});

