import { Tooltip as TooltipPrimitive } from "@ark-ui/vue/tooltip";
import type { TooltipProps as TooltipSharedProps } from "@pisagor/props";
import { type TooltipRecipeSlot, tooltipRecipe } from "@pisagor/recipes";
import {
  defineComponent,
  h,
  type PropType,
  Teleport,
  type VNodeChild,
} from "vue";
import type { VariantClassNames } from "../../internal/types";

// #region Types
export type TooltipTriggerHandle = (
  props: Record<string, unknown>,
) => VNodeChild;

type TooltipClassNames = VariantClassNames<TooltipRecipeSlot>;

export interface TooltipProps extends TooltipSharedProps {
  arrowProps?: Record<string, unknown>;
  children: VNodeChild | TooltipTriggerHandle;
  classNames?: TooltipClassNames;
  closeDelay?: number;
  content: VNodeChild;
  contentProps?: Record<string, unknown>;
  lazyMount?: boolean;
  openDelay?: number;
  positionerProps?: Record<string, unknown>;
  positioning?: Record<string, unknown>;
  triggerProps?: Record<string, unknown>;
  unmountOnExit?: boolean;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

function isTriggerHandle(
  children: VNodeChild | TooltipTriggerHandle,
): children is TooltipTriggerHandle {
  return typeof children === "function";
}

// #region Component
export const Tooltip = defineComponent({
  inheritAttrs: false,
  name: "PisagorTooltip",
  props: {
    arrowProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    children: {
      required: true,
      type: [Object, Function, String, Array] as PropType<
        VNodeChild | TooltipTriggerHandle
      >,
    },
    classNames: {
      default: undefined,
      type: Object as PropType<TooltipClassNames>,
    },
    closeDelay: { default: 150, type: Number },
    content: {
      required: true,
      type: [Object, String, Array] as PropType<VNodeChild>,
    },
    contentProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    lazyMount: { default: true, type: Boolean },
    openDelay: { default: 400, type: Number },
    positionerProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    positioning: {
      default: () => ({ placement: "top" }),
      type: Object as PropType<Record<string, unknown>>,
    },
    recipe: {
      default: tooltipRecipe,
      type: Function as PropType<typeof tooltipRecipe>,
    },
    triggerProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs }) {
    return () => {
      const slots = props.recipe();
      const trigger = isTriggerHandle(props.children)
        ? h(TooltipPrimitive.Context as ArkPart, null, {
            default: (api: {
              getTriggerProps: () => Record<string, unknown>;
            }) =>
              (props.children as TooltipTriggerHandle)(api.getTriggerProps()),
          })
        : h(
            TooltipPrimitive.Trigger as ArkPart,
            {
              ...props.triggerProps,
              asChild: true,
            },
            () => props.children,
          );

      return h(
        TooltipPrimitive.Root as ArkPart,
        {
          ...attrs,
          closeDelay: props.closeDelay,
          lazyMount: props.lazyMount,
          openDelay: props.openDelay,
          positioning: props.positioning,
          unmountOnExit: props.unmountOnExit,
        },
        () => [
          trigger,
          h(Teleport, { to: "body" }, () =>
            h(
              TooltipPrimitive.Positioner as ArkPart,
              { ...props.positionerProps },
              () =>
                h(
                  TooltipPrimitive.Content as ArkPart,
                  {
                    ...props.contentProps,
                    class: slots.content({ class: props.classNames?.content }),
                  },
                  () => [
                    h(
                      TooltipPrimitive.Arrow as ArkPart,
                      {
                        ...props.arrowProps,
                        class: slots.arrow({ class: props.classNames?.arrow }),
                      },
                      () => h(TooltipPrimitive.ArrowTip as ArkPart),
                    ),
                    props.content,
                  ],
                ),
            ),
          ),
        ],
      );
    };
  },
});
// #endregion

export {
  Tooltip,
  type TooltipProps,
  type TooltipTriggerHandle,
} from "./tooltip";

import { ark } from "@ark-ui/vue/factory";
import {
  Tour as TourPrimitive,
  type TourStepDetails,
  type UseTourReturn,
  useTour,
} from "@ark-ui/vue/tour";
import { PhCaretLeft, PhCaretRight, PhX } from "@phosphor-icons/vue";
import type { TourProps as TourRootSharedProps } from "@pisagor/props";
import { dialogRecipe, type TourRecipe, tourRecipe } from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import {
  computed,
  defineComponent,
  h,
  type PropType,
  reactive,
  ref,
  Teleport,
  toValue,
  type UnwrapRef,
  watchEffect,
} from "vue";
import { createContext } from "../../internal/utils/create-context";
import { Button } from "../button";
import { DialogBody, DialogFooter, DialogHeader } from "../dialog";

type ArkPart = Parameters<typeof h>[0];
type ClassValue = Parameters<typeof cn>[0];

// #region Types
export type TourStepType = TourStepDetails;

interface TourContextProps {
  /** The function to start the tour */
  handleStart: () => void;
  /** Slot class recipes from `tourRecipe`. */
  slots: TourRecipe;
  /** The tour instance */
  tour: UnwrapRef<UseTourReturn>;
}

export interface TourRootProps extends TourRootSharedProps {
  /** Whether to enable arrow key navigation between steps */
  keyboardNavigation?: boolean;
  /**
   * Whether to lazily mount the content
   *
   * @defaultValue true
   */
  lazyMount?: boolean;
  /** Called when the tour status changes */
  onStatusChange?: (details: { status: string }) => void;
  /** Called when the current step changes */
  onStepChange?: (details: { stepId: string | null }) => void;
  /**
   * The steps to display in the tour
   *
   * @defaultValue []
   */
  steps?: TourStepDetails[];
  /**
   * Whether to unmount the content when the tour is closed
   *
   * @defaultValue true
   */
  unmountOnExit?: boolean;
}

export interface TourBackdropProps {
  /**
   * Style recipe. Defaults to `dialogRecipe` from `@pisagor/recipes/dialog`.
   *
   * @defaultValue dialogRecipe
   */
  dialogRecipe?: typeof dialogRecipe;
  class?: unknown;
}
// #endregion

// #region Context
const [provideTourContext, , useTourContextRef] =
  createContext("Tour")<TourContextProps>();

export { useTourContextRef as useTourContext };
// #endregion

// #region Parts
export const TourRoot = defineComponent({
  inheritAttrs: false,
  name: "TourRoot",
  props: {
    keyboardNavigation: { default: undefined, type: Boolean },
    lazyMount: { default: true, type: Boolean },
    onStatusChange: {
      default: undefined,
      type: Function as PropType<TourRootProps["onStatusChange"]>,
    },
    onStepChange: {
      default: undefined,
      type: Function as PropType<TourRootProps["onStepChange"]>,
    },
    recipe: {
      default: tourRecipe,
      type: Function as PropType<typeof tourRecipe>,
    },
    steps: { default: () => [], type: Array as PropType<TourStepDetails[]> },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    const isStarted = ref(false);

    const tour = useTour(
      computed(() => ({
        keyboardNavigation: props.keyboardNavigation,
        onStatusChange: props.onStatusChange,
        onStepChange: props.onStepChange,
        steps: props.steps,
      })),
    );

    watchEffect((onCleanup) => {
      document.body.classList.toggle("relative", isStarted.value);
      onCleanup(() => document.body.classList.remove("relative"));
    });

    const handleStart = () => {
      isStarted.value = true;
      tour.value.start();
    };

    const context = reactive({
      handleStart,
      slots: props.recipe(),
      tour,
    });

    provideTourContext(context);

    return () =>
      h(
        TourPrimitive.Root as ArkPart,
        {
          ...attrs,
          lazyMount: props.lazyMount,
          tour: tour.value,
          unmountOnExit: props.unmountOnExit,
        },
        slots,
      );
  },
});

export const TourTrigger = defineComponent({
  inheritAttrs: false,
  name: "Tour.Trigger",
  setup(_, { attrs, slots }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;
      const { handleStart } = ctx;
      const onClick = attrs.onClick as
        | ((event: MouseEvent) => void)
        | undefined;

      const handleClick = (event: MouseEvent) => {
        onClick?.(event);
        handleStart();
      };

      return h(
        ark.button as ArkPart,
        {
          ...attrs,
          "data-part": "trigger",
          "data-scope": "tour",
          onClick: handleClick,
          type: "button",
        },
        slots,
      );
    };
  },
});

export const TourActionTrigger = defineComponent({
  inheritAttrs: false,
  name: "Tour.ActionTrigger",
  setup(_, { attrs, slots }) {
    return () => h(TourPrimitive.ActionTrigger as ArkPart, { ...attrs }, slots);
  },
});

export const TourBackdrop = defineComponent({
  inheritAttrs: false,
  name: "Tour.Backdrop",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    dialogRecipe: {
      default: dialogRecipe,
      type: Function as PropType<typeof dialogRecipe>,
    },
  },
  setup(props, { attrs }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;

      return h(TourPrimitive.Backdrop as ArkPart, {
        ...attrs,
        class: cn(
          props.dialogRecipe().backdrop(),
          ctx.slots.backdrop(),
          props.class,
        ),
      });
    };
  },
});

export const TourPositioner = defineComponent({
  inheritAttrs: false,
  name: "Tour.Positioner",
  setup(_, { attrs, slots }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;

      return h(
        TourPrimitive.Positioner as ArkPart,
        { class: cn(ctx.slots.positioner()), ...attrs },
        slots,
      );
    };
  },
});

export const TourContent = defineComponent({
  inheritAttrs: false,
  name: "Tour.Content",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
    showCloseButton: { default: true, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;
      const { slots: recipeSlots } = ctx;

      const defaultChildren = () => [
        h(TourHeader, null, () => [h(TourTitle), h(TourProgressText)]),
        h(TourBody, null, () => h(TourDescription)),
        h(TourFooter, null, () => [h(TourPreviousStep), h(TourNextStep)]),
      ];

      return h(Teleport, { to: "body" }, () => [
        h(TourBackdrop),
        h(TourPositioner, null, () =>
          h(
            TourPrimitive.Content as ArkPart,
            {
              ...attrs,
              class: cn(recipeSlots.content(), props.class),
            },
            () => [
              slots.default ? slots.default() : defaultChildren(),
              props.showCloseButton
                ? h(
                    TourCloseTrigger,
                    { asChild: true, class: recipeSlots.close() },
                    () =>
                      h(
                        Button as ArkPart,
                        {
                          class: recipeSlots.closeButton(),
                          size: "icon-md",
                          variant: "ghost",
                        },
                        () => [
                          h(PhX),
                          h(
                            "span",
                            { class: recipeSlots.closeLabel() },
                            "Close",
                          ),
                        ],
                      ),
                  )
                : null,
            ],
          ),
        ),
        h(TourSpotlight),
      ]);
    };
  },
});

export const TourBody = defineComponent({
  inheritAttrs: false,
  name: "Tour.Body",
  setup(_, { attrs, slots }) {
    return () =>
      h(
        DialogBody as ArkPart,
        { ...attrs, dataPart: "body", dataScope: "tour" },
        slots,
      );
  },
});

export const TourSpotlight = defineComponent({
  inheritAttrs: false,
  name: "Tour.Spotlight",
  setup(_, { attrs }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;

      return h(TourPrimitive.Spotlight as ArkPart, {
        class: ctx.slots.spotlight(),
        ...attrs,
      });
    };
  },
});

export const TourHeader = defineComponent({
  inheritAttrs: false,
  name: "Tour.Header",
  setup(_, { attrs, slots }) {
    return () =>
      h(
        DialogHeader as ArkPart,
        { ...attrs, dataPart: "header", dataScope: "tour" },
        slots,
      );
  },
});

export const TourTitle = defineComponent({
  inheritAttrs: false,
  name: "Tour.Title",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
  },
  setup(props, { attrs }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;
      const { slots: recipeSlots, tour } = ctx;

      return h(
        TourPrimitive.Title as ArkPart,
        { ...attrs, class: cn(recipeSlots.title(), props.class) },
        () => tour.step?.title,
      );
    };
  },
});

export const TourDescription = defineComponent({
  inheritAttrs: false,
  name: "Tour.Description",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
  },
  setup(props, { attrs }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;
      const { slots: recipeSlots, tour } = ctx;

      return h(
        TourPrimitive.Description as ArkPart,
        {
          ...attrs,
          class: cn(recipeSlots.description(), props.class),
        },
        () => tour.step?.description,
      );
    };
  },
});

export const TourProgressText = defineComponent({
  inheritAttrs: false,
  name: "Tour.ProgressText",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
  },
  setup(props, { attrs }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;
      const { slots: recipeSlots, tour } = ctx;

      return h(
        TourPrimitive.ProgressText as ArkPart,
        {
          ...attrs,
          class: cn(recipeSlots.progressText(), props.class),
        },
        () => tour.getProgressText(),
      );
    };
  },
});

export const TourCloseTrigger = defineComponent({
  inheritAttrs: false,
  name: "Tour.CloseTrigger",
  setup(_, { attrs, slots }) {
    return () => h(TourPrimitive.CloseTrigger as ArkPart, { ...attrs }, slots);
  },
});

export const TourFooter = defineComponent({
  inheritAttrs: false,
  name: "Tour.Footer",
  setup(_, { attrs, slots }) {
    return () =>
      h(TourPrimitive.Control as ArkPart, { ...attrs, asChild: true }, () =>
        h(DialogFooter, { dataPart: "control", dataScope: "tour" }, slots),
      );
  },
});

export const TourActions = defineComponent({
  inheritAttrs: false,
  name: "Tour.Actions",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<ClassValue>,
    },
  },
  setup(props, { attrs }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;
      const { slots: recipeSlots, tour } = ctx;
      const actions = tour.step?.actions ?? [];

      if (actions.length === 0) {
        return null;
      }

      return h(
        TourPrimitive.Control as ArkPart,
        { ...attrs, asChild: true },
        () =>
          h(
            DialogFooter as ArkPart,
            {
              class: cn(recipeSlots.actions(), props.class),
              dataPart: "actions",
              dataScope: "tour",
            },
            () =>
              actions.map((action) =>
                h(
                  TourActionTrigger,
                  { action, asChild: true, key: action.label },
                  () =>
                    h(
                      Button,
                      {
                        size: "sm",
                        variant:
                          action.action === "dismiss" ||
                          action.action === "prev"
                            ? "outline"
                            : "default",
                      },
                      () => [
                        action.action === "prev" ? h(PhCaretLeft) : null,
                        action.label,
                        action.action === "next" ? h(PhCaretRight) : null,
                      ],
                    ),
                ),
              ),
          ),
      );
    };
  },
});

export const TourPreviousStep = defineComponent({
  inheritAttrs: false,
  name: "Tour.PreviousStep",
  setup(_, { attrs }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;
      const { tour } = ctx;
      const prevAction = tour.step?.actions?.find(
        (action) => action.action === "prev",
      );

      if (!prevAction) {
        return null;
      }

      return h(
        TourActionTrigger,
        { ...attrs, action: prevAction, asChild: true },
        () =>
          h(Button, { size: "sm", variant: "outline" }, () => [
            h(PhCaretLeft),
            prevAction.label,
          ]),
      );
    };
  },
});

export const TourNextStep = defineComponent({
  inheritAttrs: false,
  name: "Tour.NextStep",
  setup(_, { attrs }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;
      const { tour } = ctx;
      const action = tour.step?.actions?.find(
        (candidate) =>
          candidate.action === "next" || candidate.action === "dismiss",
      );

      if (!action) {
        return null;
      }

      return h(TourActionTrigger, { ...attrs, action, asChild: true }, () =>
        h(Button, { size: "sm" }, () => [
          action.label,
          action.action === "next" ? h(PhCaretRight) : null,
        ]),
      );
    };
  },
});
// #endregion

