import { ark } from "@ark-ui/vue/factory";
import {
  createTreeCollection as arkCreateTreeCollection,
  type TreeCollection as arkTreeCollection,
  TreeView as TreeViewPrimitive,
} from "@ark-ui/vue/tree-view";
import {
  PhCaretRight,
  PhCheck,
  PhFile,
  PhFolder,
  PhFolderOpen,
  PhMinus,
} from "@phosphor-icons/vue";
import type {
  TreeViewBranchProps as TreeViewBranchSharedProps,
  TreeViewItemProps as TreeViewItemSharedProps,
  TreeViewItemProps as TreeViewItemTitleSharedProps,
  TreeViewProps as TreeViewSharedProps,
} from "@pisagor/props";
import {
  formControlToggleRecipe,
  treeViewBranchRecipe,
  treeViewItemRecipe,
  treeViewRecipe,
} from "@pisagor/recipes";
import { cn } from "@pisagor/utils";
import { defineComponent, Fragment, h, type PropType } from "vue";
import { createContext } from "../../internal/utils/create-context";
import { useFormControlSurface } from "../surface/use-form-control-surface";

// #region Types
export interface TreeNodeType<T = unknown> {
  children?: TreeNodeType<T>[] | undefined;
  expandedIcon?: unknown | null;
  icon?: unknown | null;
  id: string;
  name: string;
}

export type TreeCollection = arkTreeCollection;

interface TreeViewContextValue {
  fileIcons?: Record<string, unknown | null>;
}

export interface TreeViewProps extends TreeViewSharedProps {
  fileIcons?: Record<string, unknown | null>;
  lazyMount?: boolean;
  unmountOnExit?: boolean;
  class?: unknown;
}

export interface NodeProviderProps<T extends TreeNodeType = TreeNodeType> {
  value: T;
}

export interface TreeViewBranchProps extends TreeViewBranchSharedProps {
  class?: unknown;
}

export interface TreeViewItemProps extends TreeViewItemSharedProps {
  class?: unknown;
}

export interface TreeViewItemTitleProps extends TreeViewItemTitleSharedProps {
  class?: unknown;
}
// #endregion

// #region Context
const [provideTreeViewContext, useTreeViewContext] = createContext(
  "TreeViewLocal",
)<TreeViewContextValue>({
  defaultValue: {},
  strict: false,
});
// #endregion

// #region Helpers
export const createTreeCollection = <T extends TreeNodeType>(
  options: Parameters<typeof arkCreateTreeCollection<T>>[0],
) =>
  arkCreateTreeCollection<T>({
    nodeToString: (node) => node.name,
    nodeToValue: (node) => node.id,
    ...options,
  });

export const createFileIcons = (
  args: Record<`.${string}`, unknown | null>,
) => ({ ...args });

const getFileExtension = (file: string) => {
  const name = file.includes(".")
    ? file.split(".").at(-1)?.toLowerCase()
    : null;
  return name ? `.${name}` : null;
};
// #endregion

// #region Parts
type ArkPart = Parameters<typeof h>[0];

export const TreeViewRoot = defineComponent({
  inheritAttrs: false,
  name: "TreeViewRoot",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    fileIcons: {
      default: undefined,
      type: Object as PropType<Record<string, unknown | null>>,
    },
    lazyMount: { default: true, type: Boolean },
    recipe: {
      default: treeViewRecipe,
      type: Function as PropType<typeof treeViewRecipe>,
    },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    provideTreeViewContext({ fileIcons: props.fileIcons });

    return () => {
      const variantSlots = props.recipe();

      return h(
        TreeViewPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
          lazyMount: props.lazyMount,
          unmountOnExit: props.unmountOnExit,
        },
        slots.default?.(),
      );
    };
  },
});

export const TreeViewLabel = defineComponent({
  inheritAttrs: false,
  name: "TreeViewLabel",
  props: {
    class: {
      default: undefined,
      type: [String, Object, Array] as PropType<unknown>,
    },
    recipe: {
      default: treeViewRecipe,
      type: Function as PropType<typeof treeViewRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

